// `side(to) = OPPOSITE_DIR[to.dir]` rule — already lives in
// `../trace.layout.ts` where the contract was frozen (docs/TRACE-PLAN.md).
// All this adds is the assembly.

import type { TraceTerminalSpec, Point } from "../trace.layout";
import { traceSideOf } from "../trace.layout";
import type {
  ElbowPin,
  ElbowRect,
  ElbowRoute,
  ElbowRouteInput,
  ElbowRouteOptions,
  ElbowRoutingObstacle,
} from "./index";

export interface TraceElbowRequest {
  from: TraceTerminalSpec;
  to: TraceTerminalSpec;
  /** Keep-outs the route must not cross. A story fixture IS this list —
   * there is no obstacle COLLECTOR here, by design (the donor's
   * `routingObstacles.ts` reads live tldraw shapes and stayed behind). */
  obstacles?: readonly ElbowRoutingObstacle[];
  /** The owning card's box, when a terminal sits on one. Endpoint boxes get
   * the router's special treatment: the first/last leg may cross its own
   * card while leaving through the port, but no later segment may re-enter. */
  fromBox?: ElbowRect | null;
  toBox?: ElbowRect | null;
  pins?: readonly ElbowPin[];
  options?: Partial<ElbowRouteOptions>;
}

/**
 * `{x, y, dir}` pairs -> the router's `ElbowRouteInput`.
 *
 * The only interesting line is the side derivation, and it is NOT symmetric:
 * a wire LEAVES the `from` terminal along the flow, and ARRIVES at the `to`
 * terminal travelling `to.dir` — so the free space at the `to` end is BEHIND
 * it, which is `OPPOSITE_DIR[to.dir]`. Getting this backwards produces routes
 * that look plausible in the classic left-to-right case (where the two happen
 * to coincide) and loop absurdly for every other tangent, which is exactly
 * why the rule was frozen in the plan rather than re-derived per lane.
 */
export function elbowInputFromTerminals(request: TraceElbowRequest): ElbowRouteInput {
  const { from, to, obstacles, fromBox, toBox, pins, options } = request;
  return {
    start: { point: { x: from.x, y: from.y }, side: traceSideOf(from, "from"), box: fromBox ?? null },
    end: { point: { x: to.x, y: to.y }, side: traceSideOf(to, "to"), box: toBox ?? null },
    ...(obstacles ? { obstacles } : {}),
    ...(pins ? { pins } : {}),
    ...(options ? { options } : {}),
  };
}

/** The route's vertices as this app's `Point[]` — what `TraceBody`'s `points`
 * prop and `TraceBadge`'s drag math both take. A structural copy, so a caller
 * mutating it cannot reach back into a route. */
export function routePoints(route: ElbowRoute): Point[] {
  return route.points.map((point) => ({ x: point.x, y: point.y }));
}

/**
 * src/components/glyph.layout.ts — ported by value from
 * packages/bbox-ui/src/glyph.layout.ts (Glyph v2, docs/GLYPH-PLAN.md's
 * contract). Same size ladder and override-vs-preset rule; this app has no
 * `layout.ts`/`TEXT_SIZES` of its own to stay independent of, but the
 * ladder is kept in its own file anyway so `glyph.tsx` matches its source
 * shape 1:1 for anyone diffing the two later.
 *
 * DONOR LINES (read 2026-09-17; the donor is 53 lines and lives in this
 * same repo, so this is a `diff` away, not an archaeology dig):
 *   • `glyph.layout.ts:11`    `GLYPH_SIZES` — same four rungs, same values.
 *   • `glyph.layout.ts:20-43` the two interfaces.
 *   • `glyph.layout.ts:45-52` `glyphFootprint`, including the `!== undefined`
 *     rule restated below. Arithmetic unchanged.
 *
 * NO PRIOR ART IS CLAIMED, and none applies: the "ladder plus override"
 * rule and the square `size + 2*padding` footprint are this repo's own
 * product decisions, not an algorithm. There is nothing here to cite but
 * the donor.
 */
export const GLYPH_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type GlyphSize = keyof typeof GLYPH_SIZES;
export const GLYPH_SIZE_NAMES: Record<GlyphSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

export interface GlyphFootprintInput {
  sizePreset?: GlyphSize;
  /** px override — when given, wins over `sizePreset`. */
  size?: number;
  padding?: number;
}

export interface GlyphFootprint {
  /** Resolved side length of the glyph itself, px. */
  size: number;
  padding: number;
  /** Outer box a host places on canvas — `size + 2*padding`, square. */
  w: number;
  h: number;
}

/**
 * The override-vs-preset size rule, in one place. `size` absent/undefined
 * is NOT the same as `size: 0` — an explicit 0 is a real override, so this
 * checks `!== undefined`, never falsy/`??`, to keep that case distinguishable.
 */
export function glyphFootprint({
  sizePreset = "sm",
  size,
  padding = 0,
}: GlyphFootprintInput): GlyphFootprint {
  const resolvedSize = size !== undefined ? size : GLYPH_SIZES[sizePreset];
  const outer = resolvedSize + 2 * padding;
  return { size: resolvedSize, padding, w: outer, h: outer };
}

