   * `hidden` needs `points` — shortening the drawn `d` requires the route's
   * vertices, not just its serialization. Without them the cable paints in
   * full, which is the honest failure (`Trace` supplies them for every
   * routing, sampling a curve's after layout).
   */
  tunnel?: TunnelDisplayState;
  /**
   * How this cable shows it passes OVER another where they cross. `none`
   * (default) or `halo` — a background-coloured casing under this cable's
   * own stroke and over every cable painted before it. See
   * `./trace.crossing` for the research, the 11px calibration, and why the
   * seam is a style name rather than a boolean (so `hop`/`gap` can land
   * later without a rewrite).
   *
   * Defaults to `none` even though the donor's `DEFAULT_CROSSING_MARK` is
   * `halo`: a casing asserts knowledge of the canvas colour, which this
   * component can only guess through a CSS variable. Hosts opt in.
   */
  crossing?: CrossingMark;
  /**
   * The hit path's stroke width in the SVG's own units. Defaults to
   * `TRACE_HIT_STROKE_PX` (12). Scene-space, like every geometry number
   * here: under a host's viewport transform the band scales with zoom
   * (note it does NOT get the `vectorEffect` prop — that keeps the INK
   * screen-constant while the hit band still scales; see the hit-regions
   * stories). A host wanting a screen-constant band divides by its zoom.
   */
  hitStrokePx?: number;
  /**
   * Paint the hit path (translucent stroke) instead of leaving it
   * transparent. Pure paint on the EXISTING hit element — width, cap and
   * hit-testing are identical with this on or off. Only meaningful with
   * `interactive`; a non-interactive Trace HAS no hit band, and painting
   * one would be the decoration this prop exists to avoid.
   */
  showHitRegion?: boolean;
  /**
   * The diagnostic axis (docs/INVALID-STATES-PLAN.md §5's Trace row): a
   * mark under the wire, same geometry as the hit path, painted at
   * `max(severity)`. The visible stroke itself keeps its own variant
   * colour/dash — `data`/`async`/`delayed` stay legible — so the mark is
   * the ONLY thing this axis owns here. `info` paints nothing (§5's
   * table).
   *
   * WHY hover, not an inline badge (Zach's report feedback, reacting to
   * the proposal's own "message rides `TraceBadge` in severity dress"
   * mock): "I wonder if instead of display the error text directly on it,
   * we instead follow the language of always showing the exact
   * information in a pop out modal" — the wire is marked, exactly like
   * every other element this axis touches, and the message lives in the
   * hover `Tooltip` this file wraps its own marked output in
   * (`DiagnosticTooltip`, ./highlighter.tsx), never baked onto the
   * geometry. A host that still wants a `TraceBadge` on the line is free
   * to add one for its OWN reasons — this axis no longer proposes it.
   */
  diagnostics?: Diagnostic[];
  /** Which `HighlighterKind` draws the mark. Defaults to
   *  `DEFAULT_HIGHLIGHTER_KIND` ("stroke") — Zach's own lean from the
   *  report feedback; `"halo"` is the pre-existing translucent-backdrop
   *  treatment, kept as a sibling, not deleted. `"mask"` aliases to
   *  `"stroke"` here: JointJS's mask technique targets an enclosed
   *  shape's interior, and an open path has none — a round-joined offset
   *  line already gives a path the equidistant-at-bends property `mask`
   *  is for, so there is no separate technique to build. */
  highlighterKind?: HighlighterKind;
}

export interface TraceStrokeStyle {
  strokeDasharray?: string;
  strokeDashoffset?: number;
  strokeLinecap: "round" | "butt";
  /** Marching-ants class — DATA ONLY, never applied as a side effect by
   * this function. The caller puts it on the rendered element's
   * `className`, never inside `style`. */
  className?: string;
}

/**
 * Pure — no DOM. Dash MECHANICS only (pattern, phase/offset, the
 * marching-ants class NAME), never colour: colour is a plain `color` prop
 * here, resolved nowhere. An adapter calls this directly when assembling
 * React Flow's own `BaseEdge` `style` prop for the single-stroke variants.
 */
export function traceStrokeStyle(
  variant: TraceVariant,
  length: number,
  animated = false,
): TraceStrokeStyle {
  if (variant === "async") {
    return {
      strokeDasharray: ASYNC_PACKET_DASHARRAY,
      strokeDashoffset: asyncDashOffsetForLength(length),
      strokeLinecap: "butt",
    };
  }
  if (variant === "delayed") {
    return {
      strokeDasharray: `${DELAY_DOT_PX} ${DELAY_DOT_GAP_PX}`,
      strokeLinecap: "round",
    };
  }
  const marching = animated;
  return {
    strokeDasharray: marching ? DATA_MARCH_DASHARRAY : undefined,
    strokeLinecap: marching ? "butt" : "round",
    className: marching ? DATA_MARCH_CLASS : undefined,
  };
}

/** Marker geometry lives once, referenced by every variant that draws a
 * head — the open two-stroke chevron `SlantedArrowBody` established.
 * `context-stroke` (a real SVG2 paint keyword; broad Chromium/Firefox
 * support per MDN, NOT YET Safari — there the marker falls back to its own
 * unspecified default stroke rather than erroring, a degraded look, not a
 * broken one) makes it inherit whatever stroke paints the line beside it,
 * so it never needs a second colour derivation or a duplicate marker per
 * colour. */
export function TraceMarkerDef({ id }: { id: string }) {
  return (
    <marker
      data-slot="trace-marker"
      id={id}
      viewBox="0 0 10 10"
      refX="8.5"
      refY="5"
      markerWidth="7"
      markerHeight="7"
      orient="auto"
      overflow="visible"
    >
      <path
        data-slot="trace-marker-head"
        d="M 1 1 L 9 5 L 1 9"
        fill="none"
        stroke="context-stroke"
        strokeWidth={2}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </marker>
  );
}

/**
 * The paint — one visible `<path>` for `data`/`async`, two for a `delayed`
 * trace with `splitAtLabel`, plus the optional invisible hit path. Zero
 * imports of any canvas engine.
 */
export function TraceBody({
  id,
  path,
  length,
  points,
  variant = "data",
  color = "var(--muted-foreground)",
  animated = false,
  splitAtLabel = false,
  labelPosition = LABEL_POSITION_DEFAULT,
  markerEnd = DEFAULT_TRACE_MARKER_END,
  strokeWidth = TRACE_STROKE_WIDTH_PX,
  vectorEffect,
  interactive = false,
  tunnel = "off",
  crossing = "none",
  hitStrokePx = TRACE_HIT_STROKE_PX,
  showHitRegion = false,
  diagnostics,
  highlighterKind = DEFAULT_HIGHLIGHTER_KIND,
  className,
  ...props
}: TraceProps) {
  const markerId = safeElementId("bbox-trace-head", id);
  const diagnosticSeverity = maxDiagnosticSeverity(diagnostics);
  const hasMarker = markerEnd !== "none";
  const markerAttr = hasMarker ? `url(#${markerId})` : undefined;
  const resolvedLength = length ?? (points ? polylineLength(points) : 0);

  // ---- Tunnel -----------------------------------------------------------
  // `revealed` passes `true` and gets null back — that IS the donor's
  // contract ("`null` means the route should remain fully visible"), so
  // revealed needs no branch of its own here.
  const tunnelVisual =
    tunnel !== "off" && points ? tunnelVisualForPoints(points, tunnel === "revealed") : null;
  // Only `hidden` shortens the path. `preview` keeps the whole route AND
  // the mouths — the single most confusable thing about this feature, which
  // is why it reads as a named predicate rather than a string compare.
  const mouths =
    tunnelVisual && tunnelHidesRun(tunnel) && points ? tunnelMouths(points, false) : null;
  // Two subpaths in ONE `d`, not two elements: the marker then still lands
  // on the target end (a marker-end attaches to the final vertex of the last
  // subpath), the dash channel stays free for the variant, and
  // `flattenPathData` already treats each `M` as a separate sketch run.
  const drawnPath = mouths
    ? `${polylinePath(mouths.start)} ${polylinePath(mouths.end)}`
    : path;
  const drawnLength = mouths ? TUNNEL_STUB_LENGTH * 2 : resolvedLength;
  const showVias = tunnelVisual !== null && tunnelShowsVias(tunnel);

  // ---- Crossing mark ----------------------------------------------------
  // Measured on the DRAWN length, which makes the tunnel case correct for
  // free: two 34px stubs fall under `CROSSING_CASING_MIN_LENGTH`, so a
  // tunnelled cable gets no casing — there is no middle left to protect.
  const casingDash = crossing === "halo" ? casingDashArray(drawnLength) : null;

  const defs = hasMarker ? (
    <defs data-slot="trace-defs">
      <TraceMarkerDef id={markerId} />
    </defs>
  ) : null;

  // Painted FIRST — before the hit path, before this cable's own stroke —
  // because paint order IS the algorithm: the cable drawn later lays its
  // background casing across the one drawn earlier, so the upper line reads
  // as passing over the lower one with no intersection computed anywhere.
  //
  // WHY this never gets a drawn twin: it is `data-slot="trace-casing"`, not
  // `"trace-line"`, so `sketchAtEdge.ts`'s boundary pass does not select it
  // at all (docs/peps/0001-sketch-skin-at-the-boundary.md). That is also
  // the right call on the merits — the casing is the canvas colour, so it
  // is invisible on its own and exists only to occlude. An 11px stroke
  // swallows the sketch skin's ~1.4px wobble whole, so a drawn copy would
  // cost a path and change nothing. `pointerEvents: none` because a wide
  // invisible stroke that ate clicks would be a hit target nobody asked
  // for.
  const casing = casingDash ? (
    <path
      data-slot="trace-casing"
      d={drawnPath}
      fill="none"
      stroke={CROSSING_CASING_COLOR}
      strokeWidth={CROSSING_CASING_WIDTH}
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeDasharray={casingDash}
      style={{ pointerEvents: "none" }}
    />
  ) : null;

  // The honest remainder of a hidden long run: two outlined landing points
  // make "continues elsewhere" distinct from "disconnected".
  const vias = showVias ? (
    <g data-slot="trace-vias" style={{ color: color, pointerEvents: "none" }}>
      <circle
        data-via="start"
        cx={tunnelVisual.startVia.x}
        cy={tunnelVisual.startVia.y}
        r={TUNNEL_VIA_RADIUS}
        fill={CROSSING_CASING_COLOR}
        stroke="currentColor"
        strokeWidth={2}
      />
      <circle
        data-via="end"
        cx={tunnelVisual.endVia.x}
        cy={tunnelVisual.endVia.y}
        r={TUNNEL_VIA_RADIUS}
        fill={CROSSING_CASING_COLOR}
        stroke="currentColor"
        strokeWidth={2}
      />
    </g>
  ) : null;

  // Painted FIRST so the visible line always sits on top of it. It is
  // transparent, not `opacity:0` — a transparent stroke still hit-tests
  // with `pointer-events: stroke`, which is the entire point.
  // WHY `drawnPath` and not `path`: a tunnelled cable's hidden middle is not
  // there, so it must not be hoverable either. Zach's own note on the
  // feature is "hover previews the route with its tunnel mouths" — the mouth
  // is the affordance; a hit target tracing the invisible run would make
  // empty canvas react and would make the preview impossible to escape.
  const hit = interactive ? (
    <path
      data-slot="trace-hit"
      d={drawnPath}
      fill="none"
      stroke={showHitRegion ? HIT_REGION_STROKE : "transparent"}
      strokeWidth={hitStrokePx}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ pointerEvents: "stroke" }}
    />
  ) : null;

  // §5's Trace row: a translucent backdrop under the wire, same geometry
  // as the hit path above (`drawnPath`, so a tunnelled cable's backdrop
  // stops at the same mouths the wire itself does), painted at
  // `max(severity)`. `info` paints nothing (§5's own table). The visible
  // stroke's `color`/dash stay whatever the variant already set — this is
  // the ONLY layer the diagnostic axis owns here, never a recoloured line.
  // `"halo"` keeps the pre-existing wide, translucent wash; `"stroke"`
  // (the new default) and `"mask"` (which aliases to it here — see this
  // file's own `HighlighterKind` doc above) draw a crisp, OPAQUE, thinner
  // parallel line instead — still painted behind the visible stroke
  // (document order = paint order in SVG), just a different rendering of
  // the same "one extra layer, geometry never recoloured" contract.
  const diagnosticBackdrop =
    diagnosticSeverity && diagnosticSeverity !== "info" ? (
      <path
        data-slot="trace-diagnostic-backdrop"
        data-highlighter-kind={highlighterKind}
        aria-hidden
        d={drawnPath}
        fill="none"
        stroke={
          highlighterKind === "halo"
            ? `color-mix(in srgb, ${diagnosticColorVar(diagnosticSeverity)} 30%, transparent)`
            : diagnosticColorVar(diagnosticSeverity)
        }
        strokeWidth={highlighterKind === "halo" ? 10 : 4}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ pointerEvents: "none" }}
      />
    ) : null;


  // A hidden middle has no label seam to split at — `splitAtLabel` puts the
  // solid/dotted boundary at `labelPosition` along the FULL route, which is
  // exactly the stretch that has left the surface. So a tunnelled `delayed`
  // trace falls through to the single-path branch and keeps its dots; it
  // does not silently draw a split across two 34px stubs.
  if (variant === "delayed" && splitAtLabel && !mouths) {
    const dash = splitDashArrays(resolvedLength, clampLabelPosition(labelPosition));
    const splitSegment = {
      pathLength: PATH_LENGTH_UNITS,
      fill: "none",
      stroke: color,
      strokeLinecap: "round" as const,
      strokeLinejoin: "round" as const,
      strokeWidth,
      vectorEffect,
    };
    return (
      // Hover -> Tooltip (message + code, no actions), the same §5
      // contract every other marked element wraps its output in — and,
      // per Zach's report feedback, the ONLY place the message rides on
      // Trace now (no inline badge baked onto the wire).
      <DiagnosticTooltip diagnostics={diagnostics}>
      <g
        data-slot="trace"
        data-variant={variant}
        data-split="true"
        data-tunnel={tunnel}
        data-crossing={crossing}
        data-diagnostic={diagnosticSeverity}
        className={cn(className)}
        {...props}
      >
        {defs}
        {diagnosticBackdrop}
        {casing}
        {hit}
        <path {...splitSegment} data-slot="trace-line" data-trace-segment="before" d={path} strokeDasharray={dash.before} />
        <path {...splitSegment} data-slot="trace-line" data-trace-segment="after" d={path} strokeDasharray={dash.after} markerEnd={markerAttr} />
        {vias}
      </g>
      </DiagnosticTooltip>
    );
  }

  // WHY `drawnLength` and not `resolvedLength`: the dash phase has to
  // describe the path that is actually painted. A tunnelled cable draws two
  // 34px stubs, and 34 is well under one async cadence (74px) — fed the
  // full route length, `asyncDashOffsetForLength` returns 0, both stubs
  // land inside the 56px carrier, and an async cable silently renders
  // solid. Caught by LOOKING at the capture, not by a test: every
  // attribute-level assertion passed. Fed the drawn length instead, the
  // short-run branch that already exists for exactly this case centres one
  // gap-packet-gap mark in each mouth. Identical to `resolvedLength`
  // whenever nothing is tunnelled.
  //
  // It is ONE MOUTH's length, not both: `asyncDashOffsetForLength`'s
  // contract is "centre a mark in a run of this length", and SVG restarts
  // the dash pattern at each subpath — so the run it phases is a single
  // stub, twice, not their sum.
  const dashStyle = traceStrokeStyle(variant, mouths ? TUNNEL_STUB_LENGTH : drawnLength, animated);
  const segment = {
    fill: "none",
    stroke: color,
    strokeWidth,
    strokeLinecap: dashStyle.strokeLinecap,
    strokeLinejoin: "round" as const,
    strokeDasharray: dashStyle.strokeDasharray,
    strokeDashoffset: dashStyle.strokeDashoffset,
    vectorEffect,
    className: dashStyle.className,
    markerEnd: markerAttr,
  };
  return (
    // Hover -> Tooltip (message + code, no actions) — see the split-label
    // branch above for the full WHY; identical contract here.
    <DiagnosticTooltip diagnostics={diagnostics}>
    <g
      data-slot="trace"
      data-variant={variant}
      data-animated={animated || undefined}
      data-tunnel={tunnel}
      data-crossing={crossing}
      data-diagnostic={diagnosticSeverity}
      className={cn(className)}
      {...props}
    >
      {defs}
      {diagnosticBackdrop}
      {casing}
      {hit}
      <path {...segment} data-slot="trace-line" data-trace-segment="whole" d={drawnPath} />
      {vias}
    </g>
    </DiagnosticTooltip>
  );
}

/* ==========================================================================
 * Trace — the wrapper (docs/TRACE-PLAN.md P6)
 *
 * `TraceBody` above is props-in, DOM-out and derives nothing. `Trace` is the
 * one place in this app allowed to derive: it takes the two frozen
 * `TraceTerminalSpec`s and a `routing` kind, asks P2 (`routeTrace`) or P3
 * (`routeElbow`) for the geometry, and paints the line plus the two terminal
 * glyphs. Everything below is net-new; nothing here is a port.
 * ========================================================================== */

/**
 * How far short of a terminal's CENTRE the wire stops, along the flow.
 *
 * WHY the wire cannot simply end at `{x, y}`: the glyph's disc is opaque
 * (deliberately — see `traceTerminal.tsx`) with r=9, and the chevron marker
 * reaches ~12px back from the path's end. A wire drawn to the exact centre
 * therefore loses BOTH its arrowhead and its last 9px under the disc.
 *
 * `TraceElbow.stories.tsx` computes the identical pull-back inline
 * (`routeStart`/`routeEnd`, `TERMINAL_GAP = 16`) because it was written
 * before this wrapper existed. That file is another lane's and is left
 * alone; the two agreeing is asserted in `TracePolarity.stories.tsx` rather
 * than assumed, so the duplication cannot drift silently.
 */
export const TRACE_TERMINAL_GAP = 16;

/**
 * The pull-back that ends a wire ON a round glyph's painted outer edge —
 * a real `Port` dot's outer ring, or `Trace`'s own terminal ring — instead
 * of short of it.
 *
 * WHY: Zach, 2026-09-22 — "Please also make the trace end exactly at the
 * port … right now there is this spacing which is not desirable!" The
 * spacing was {@link TRACE_TERMINAL_GAP}: 16px sized for `Trace`'s OWN
 * r=9 glyph plus a chevron's ~7px of reach, applied unchanged by every
 * host whose ends are real `Port` dots (5.5-6px painted radius) and, since
 * the same day, carry no chevron at all (`DEFAULT_TRACE_MARKER_END`). The
 * fixed number was the bug; the geometry the line has to meet is the
 * dot's, so a host measures that radius and hands it here.
 *
 * The pull-back depends on the line CAP, because the cap is ink past the
 * path's last point and the INK is what has to touch the ring:
 *   - `round` / `square` reach `strokeWidth / 2` past the end, so the path
 *     stops that much further back — without it the cap would paint a pixel
 *     INTO the ring, and every DOM-canvas wire paints above the dots
 *     (`wireLayer.tsx`'s D-B1 note);
 *   - `butt` reaches nothing past the end, so the path stops ON the ring.
 * WHY per cap (re-judge of d97f5ec, 2026-09-22): the first version added
 * the half-stroke for every cap, which left the butt-capped async dash a
 * visible 1px of daylight short of its ring — and the parity oracle hid it
 * by adding the same half-stroke back. A host that knows the wire's
 * variant passes {@link traceLinecapOf}'s answer; the default stays
 * `round`, the cap of every solid cable.
 */
export type TraceLinecap = "round" | "butt" | "square";

export function traceRingGapPx(ringOuterRadiusPx: number, strokeWidth: number = TRACE_STROKE_WIDTH_PX, linecap: TraceLinecap = "round"): number {
  return linecap === "butt" ? ringOuterRadiusPx : ringOuterRadiusPx + strokeWidth / 2;
}

/** The cap a variant paints with — `traceStrokeStyle`'s own answer, so the
 *  pull-back and the paint can never disagree about which cap is drawn. */
export function traceLinecapOf(variant: TraceVariant = "data", animated = false): TraceLinecap {
  return traceStrokeStyle(variant, 0, animated).strokeLinecap;
}

/**
 * The `gap` a `Trace` uses when its caller gives none — exported so a
 * component that computes the SAME geometry itself (`TraceEditor` places
 * its handles off `traceGeometry` synchronously) cannot drift from what is
 * drawn. Without a chevron to seat, the line runs all the way to the
 * glyph's ring (`traceRingGapPx`); the 16px {@link TRACE_TERMINAL_GAP} is
 * only the room an arrowhead needs, so it applies only when one is asked
 * for.
 */
export function traceDefaultGapPx({
  markerEnd = DEFAULT_TRACE_MARKER_END,
  terminalRadius = TRACE_TERMINAL_RADIUS,
  strokeWidth = TRACE_STROKE_WIDTH_PX,
  variant = "data",
  animated = false,
}: { markerEnd?: TraceMarkerEnd; terminalRadius?: number; strokeWidth?: number; variant?: TraceVariant; animated?: boolean } = {}): number {
  return markerEnd === "arrow"
    ? TRACE_TERMINAL_GAP
    : traceRingGapPx(terminalRadius + TRACE_TERMINAL_RING_PX / 2, strokeWidth, traceLinecapOf(variant, animated));
}

/** How many points a curved route is sampled into when a caller asks for a
 * polyline (`onGeometry`). A Bezier genuinely has no vertices — this is a
 * SAMPLE, and it is named one. */
export const TRACE_CURVE_SAMPLES = 64;

/** Everything `Trace` needs to compute a route, with no React in sight — so
 * a play function can ask for the same geometry the component drew without
 * rendering anything. */
export interface TraceRouteRequest {
  from: TraceTerminalSpec;
  to: TraceTerminalSpec;
  routing: TraceRouting;
  /** Pull-back at each end; defaults to {@link TRACE_TERMINAL_GAP} here.
   *  (The `Trace` COMPONENT resolves its own default from `markerEnd`
   *  before it calls this — see `TraceRouteProps.markerEnd`.) */
  gap?: number;
  /** `straight` / `curved`: the dragged centre control point. */
  curve?: TraceCurve | null;
  /** `slanted`: where along the departure axis the bend sits, 0..1. */
  slantT?: number | null;
  /** `straight` only: N intermediate control points, chord-relative
   * (docs/TRACE-CONTROL-POINTS-PLAN.md D1/D2). Ignored by every other
   * routing — see `trace.routing.ts`'s `TraceRouteOptions.bends`. */
  bends?: readonly TraceBend[] | null;
  /** `elbow`: persisted bends. */
  pins?: readonly ElbowPin[];
  /** `elbow`: keep-outs. A story fixture IS this list. */
  obstacles?: readonly ElbowRoutingObstacle[];
  fromBox?: ElbowRect | null;
  toBox?: ElbowRect | null;
  elbowOptions?: Partial<ElbowRouteOptions>;
}

export interface TraceGeometry {
  routing: TraceRouting;
  /** The SVG `d` handed to `TraceBody`. */
  path: string;
  /**
   * Exact vertices, or `null` for a curve — a cubic HAS no vertices, and
   * `routeTrace` already says so rather than inventing some. A caller that
   * needs a polyline for a curve gets a SAMPLED one from `onGeometry`,
   * measured off the mounted `SVGPathElement`, and it is labelled `sampled`.
   */
  points: Point[] | null;
  /**
   * Arc length. Exact for `straight`/`slanted`. For `elbow` this is the
   * ROUTE's length, which slightly overstates the DRAWN length because
   * `elbowPath` rounds every corner (a rounded corner is shorter than the
   * two half-segments it replaces — at most `(2 - pi/2) * r` ≈ 3.4px per
   * corner at r=8). Stated rather than silently accepted: it moves an async
   * dash phase by a few pixels and nothing else. `0` for an unmeasured
   * curve, replaced by the real `getTotalLength()` once mounted.
   */
  length: number;
  /** The exit sides the ROUTER was actually given — one derivation, read
   * back rather than recomputed (see the elbow branch's note). */
  sides: { start: TraceDir; end: TraceDir };
  /** Where a centre control point sits for this routing. */
  waypoint: Point;
  /** The route's real endpoints: the terminals pulled back by `gap`. */
  start: TraceTerminalSpec;
  end: TraceTerminalSpec;
}

/** The route's start: `gap` along the flow, out of the glyph. */
export function traceRouteStart(from: TraceTerminalSpec, gap: number): TraceTerminalSpec {
  return {
    x: from.x + DIR_VECTOR[from.dir].x * gap,
    y: from.y + DIR_VECTOR[from.dir].y * gap,
    dir: from.dir,
  };
}

/**
 * The route's end: `gap` BEHIND the target, measured along the direction of
 * travel, so the arrowhead sits in the gap pointing at the glyph. For
 * `dir: "left"` that puts the wire's last point to the RIGHT of the
 * terminal — the wrap-around case, not a sign error.
 */
export function traceRouteEnd(to: TraceTerminalSpec, gap: number): TraceTerminalSpec {
  return {
    x: to.x - DIR_VECTOR[to.dir].x * gap,
    y: to.y - DIR_VECTOR[to.dir].y * gap,
    dir: to.dir,
  };
}

/**
 * The one dispatch that spans both routing lanes. Pure: no React, no DOM.
 *
 * WHY it lives here and not in `trace.routing.ts`: that module's header
 * states, and enforces with its `DirectRouting` type, that a 450-line
 * geometry file has no business importing 2,500 lines of A*. The wrapper is
 * the seam where the two legitimately meet, so the import weight lands on
 * the component that actually needs both.
 */
export function traceGeometry(request: TraceRouteRequest): TraceGeometry {
  const gap = request.gap ?? TRACE_TERMINAL_GAP;
  return traceGeometryBetween(
    traceRouteStart(request.from, gap),
    traceRouteEnd(request.to, gap),
    request,
  );
}

/**
 * The routing half on its own, over endpoints that are ALREADY pulled back.
 *
 * WHY this is a separate function and not an implementation detail inlined
 * into `traceGeometry`: the gap pull-back consumes `dir` too — moving the
 * endpoint 16px along the flow — so a naive "permute `to.dir` and see if the
 * path changes" test answers TRUE for every routing, `straight` included,
 * because the endpoint moved. Measured before it was believed (2026-09-17):
 * with the pull-back folded in, `straight` reported `readsTo = true`, which
 * flatly contradicts docs/TRACE-PLAN.md's "straight is tangent-blind
 * everywhere" and would have shipped a gallery captioning a plain chord as
 * tangent-aware. `traceReadsTangent` therefore pulls back ONCE with the
 * request's real dirs and permutes only the `dir` the ROUTER sees, which is
 * the question actually being asked.
 */
export function traceGeometryBetween(
  start: TraceTerminalSpec,
  end: TraceTerminalSpec,
  request: Omit<TraceRouteRequest, "from" | "to" | "gap">,
): TraceGeometry {
  if (request.routing === "elbow") {
    const input = elbowInputFromTerminals({
      from: start,
      to: end,
      ...(request.obstacles ? { obstacles: request.obstacles } : {}),
      fromBox: request.fromBox ?? null,
      toBox: request.toBox ?? null,
      ...(request.pins ? { pins: request.pins } : {}),
      ...(request.elbowOptions ? { options: request.elbowOptions } : {}),
    });
    const route = routeElbow(input);
    const points = routePoints(route);
    return {
      routing: "elbow",
      path: elbowPath(route),
      points,
      length: polylineLength(points),
      // Read back off the input the ROUTER was actually given, never
      // re-derived from the terminals. Mutation testing (2026-09-17) found
      // why that distinction has teeth: an earlier version computed `sides`
      // here with its own `traceSideOf` call, and breaking THAT copy —
      // dropping the `OPPOSITE_DIR` flip at the `to` end — changed nothing
      // anyone could observe, because the router had already derived the
      // real sides inside `elbowInputFromTerminals`. A second derivation of
      // one number is how the two stop agreeing; there is now only one.
      sides: { start: input.start.side, end: input.end.side },
      // The middle of the polyline: for an elbow the "centre control point"
      // is a PIN, not an offset, so the honest waypoint is just the route's
      // own midpoint rather than a number a pin could be read back out of.
      // Shared with `straight`'s own polyline midpoint (D2 of
      // docs/TRACE-CONTROL-POINTS-PLAN.md) via `trace.layout.ts`'s
      // `pointAtFraction` — this file used to carry a second, near-identical
      // restatement of that same arc-length walk (`pointAtPolylineFraction`
      // below), which is exactly the kind of drift the plan calls out: "do
      // not invent a second rule." One function now serves both branches.
      waypoint: pointAtFraction(points, 0.5),
      start,
      end,
    };
  }

  const route = routeTrace(request.routing as DirectRouting, start, end, {
    curve: request.curve ?? null,
    slantT: request.slantT ?? null,
    bends: request.bends ?? null,
  });
  return {
    routing: route.routing,
    path: route.path,
    points: route.points,
    length: route.points ? polylineLength(route.points) : 0,
    sides: route.sides,
    waypoint: route.waypoint,
    start,
    end,
  };
}

/**
 * Does `routing` actually READ the flow tangent at `end`, for THIS request?
 *
 * MEASURED, never tabled. `trace.routing.ts` defines "blind" falsifiably —
 * "the returned geometry is INVARIANT under changing that end's `dir`" — so
 * this permutes that end's `dir` through all four values with every other
 * input held fixed and counts distinct `path` strings. One distinct path
 * means the function never looked; more than one means it did.
 *
 * WHY this and not `honorsTangent` from `trace.routing.ts`:
 *
 *  1. That table has no `elbow` row, by its own deliberate choice ("this
 *     lane asserting something about a router it does not own"). This
 *     covers elbow for free, because it never names a routing.
 *  2. The table is GEOMETRY-INDEPENDENT and therefore wrong on a degenerate
 *     chord: `TRACE_ROUTING_TANGENTS.slanted.from` is a flat `"honored"`,
 *     but `getSlantedArrowPoints` returns `[start, end]` — ignoring the
 *     departure entirely — the moment `|dx|` or `|dy|` drops under 0.001.
 *     A gallery built on the natural axis-aligned layout would have
 *     captioned a plain chord "leaves along from.dir". Measuring instead of
 *     asking cannot make that mistake, and `Degenerate` renders exactly
 *     that case to prove the difference is real rather than theoretical.
 *
 * NOT the whole story on its own: reading a tangent and ARRIVING along it
 * are two different facts, and a chord can arrive along `to.dir` by
 * coincidence without ever reading it (the plan's own "chord happens to
 * align"). `TracePolarity.stories.tsx` measures the arrival angle off the
 * rendered path and requires BOTH.
 */
export function traceReadsTangent(request: TraceRouteRequest, end: "from" | "to"): boolean {
  const gap = request.gap ?? TRACE_TERMINAL_GAP;
  // Pulled back ONCE, with the request's real dirs, and then held fixed —
  // see `traceGeometryBetween` for why folding the pull-back into the
  // permutation makes every routing look tangent-aware.
  const start = traceRouteStart(request.from, gap);
  const end_ = traceRouteEnd(request.to, gap);
  const paths = new Set(
    TRACE_DIRS.map(
      (dir) =>
        traceGeometryBetween(
          end === "from" ? { ...start, dir } : start,
          end === "to" ? { ...end_, dir } : end_,
          request,
        ).path,
    ),
  );
  return paths.size > 1;
}

// WHY `from` and `to` are omitted from the `<g>` props (the same collision
// `TraceBody` hit with `points`, and caught the same way — by `tsc`, not by a
// cast): React's `SVGProps` gives every SVG element the SMIL animation
// attributes `from`/`to`, typed `string | number`. The two terminal props
// below are the genuine names for this component, so the animation
// attributes are what give way.
export interface TraceRouteProps
  extends Omit<ComponentProps<"g">, "id" | "from" | "to">,
    Omit<TraceRouteRequest, "routing"> {
  /** Host id — hex-encoded into the marker id, exactly as `TraceBody` says. */
  id: string;
  /** Defaults to {@link DEFAULT_TRACE_ROUTING} (`elbow`). `curved` held
   * this slot until 2026-09-19 — it is the only one of the four that
   * honours both flow tangents with no control point touched, which is why
   * it was the kit's own default — but Zach's ruling is flat: "by default
   * elbow arrows should always be used. never straight arrows". All four
   * stay selectable BY NAME; only the unstated case moved. */
  routing?: TraceRouting;
  variant?: TraceVariant;
  color?: string;
  animated?: boolean;
  splitAtLabel?: boolean;
  labelPosition?: number;
  /** See `TraceProps.markerEnd`. Also picks the default `gap`: with no
   *  head the line meets the terminal ring (`traceRingGapPx`), with one it
   *  keeps `TRACE_TERMINAL_GAP`'s room for the chevron. */
  markerEnd?: TraceMarkerEnd;
  strokeWidth?: number;
  vectorEffect?: "non-scaling-stroke";
  interactive?: boolean;
  /** See `TraceProps.tunnel`. `Trace` additionally SUPPLIES the points a
   * `hidden` tunnel needs — including a curve's, sampled off the mounted
   * path — so tunnelling works on every routing kind here. */
  tunnel?: TunnelDisplayState;
  /** See `TraceProps.crossing`. */
  crossing?: CrossingMark;
  /** Forwarded to `TraceBody` — see its own doc. */
  hitStrokePx?: number;
  /** Forwarded to `TraceBody` — see its own doc. */
  showHitRegion?: boolean;
  /** Forwarded to `TraceBody` — see its own doc. */
  diagnostics?: Diagnostic[];
  /** Forwarded to `TraceBody` — see its own doc. */
  highlighterKind?: HighlighterKind;
  /** Draw the two endpoint glyphs. On by default — `Trace` is "the whole
   * thing"; a host with real `Port`s passes `false`. */
  terminals?: boolean;
  terminalRadius?: number;
  terminalColor?: string;
  /** Fired with the resolved geometry after layout, so a host can hand the
   * polyline to `TraceBadge`. For a curve the `points` handed over are
   * SAMPLED off the mounted path (`TRACE_CURVE_SAMPLES`) and `length` is the
   * real `getTotalLength()`. */
  onGeometry?: (geometry: TraceGeometry) => void;
  curveSamples?: number;
}

/**
 * Two terminal specs and a routing kind in, the whole drawn thing out.
 *
 * The curve measurement, and why it needs a layout effect at all: a cubic's
 * arc length is not available from the control points without an integral,
 * and the browser already computes it exactly — `getTotalLength()`. So a
 * curved trace paints once with `length: 0` (which changes nothing for
 * `data`, and only the dash PHASE for `async` on a path shorter than one
 * 74px cadence), then re-renders with the measured value. Stated plainly
 * because "one extra render on curves" is a real cost, not an invisible one.
 */
export function Trace({
  from,
  to,
  routing = DEFAULT_TRACE_ROUTING,
  gap,
  curve,
  slantT,
  bends,
  pins,
  obstacles,
  fromBox,
  toBox,
  elbowOptions,
  id,
  variant = "data",
  color,
  animated,
  splitAtLabel,
  labelPosition,
  markerEnd = DEFAULT_TRACE_MARKER_END,
  strokeWidth,
  vectorEffect,
  interactive,
  tunnel = "off",
  crossing = "none",
  hitStrokePx,
  showHitRegion,
  diagnostics,
  highlighterKind,
  terminals = true,
  terminalRadius,
  terminalColor,
  onGeometry,
  curveSamples = TRACE_CURVE_SAMPLES,
  className,
  ...props
}: TraceRouteProps) {
  // Geometry AND per-end arrow fidelity, derived together — see
  // `TraceTerminal`'s own `showDirection` doc for the underlying claim.
  // WHY this lives here rather than being left to each caller: `Trace` is
  // already the one place that turns a routing KIND into geometry (this
  // file's own P6 header), so it is the one place that can honestly answer
  // "does the picture I'm about to draw actually depend on this end's
  // dir" without a caller re-deriving `traceReadsTangent` itself (which
  // would either duplicate this call or, worse, hardcode routing names —
  // exactly the trap `TracePolarity.stories.tsx` documents at length).
  // Measured with `traceReadsTangent`, never read off a static per-routing
  // table: `routingTangents`'s own table is geometry-INDEPENDENT and wrong
  // on a bent curve or a degenerate slanted chord (see that function's doc
  // comment), and a terminal glyph that trusted the table over the actual
  // geometry would repeat the exact bug this component exists to fix.
  const resolvedGap = gap ?? traceDefaultGapPx({ markerEnd, terminalRadius, strokeWidth, variant, animated });
  const { geometry, showFromDirection, showToDirection } = useMemo(() => {
    const request: TraceRouteRequest = {
      from,
      to,
      routing,
      gap: resolvedGap,
      curve,
      slantT,
      bends,
      pins,
      obstacles,
      fromBox,
      toBox,
      elbowOptions,
    };
    return {
      geometry: traceGeometry(request),
      showFromDirection: traceReadsTangent(request, "from"),
      showToDirection: traceReadsTangent(request, "to"),
    };
  },
    // WHY the two terminals and `curve` are spread into scalars rather than
    // listed as objects: a caller writing `from={{ x, y, dir: "right" }}`
    // inline — which every story here does, and which is the natural way to
    // use this — would otherwise hand a fresh object identity on every render
    // and re-run the A* router each time. The elbow collections BELOW are
    // still compared by identity, because they have no fixed shape to spread;
    // a host that rebuilds its obstacle array every frame pays for a re-route
    // every frame, and that is the one perf footgun in this component.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      from.x, from.y, from.dir,
      to.x, to.y, to.dir,
      routing, resolvedGap,
      curve?.dx, curve?.dy, slantT,
      bends, pins, obstacles, fromBox, toBox, elbowOptions,
    ],
  );

  const hostRef = useRef<SVGGElement | null>(null);
  const [measuredLength, setMeasuredLength] = useState<number | null>(null);
  // A curve has no vertices until the browser has one — and `tunnel:
  // "hidden"` needs vertices to slice its two mouths out of. The effect
  // below already samples them for `onGeometry`; keeping them lets a curved
  // cable tunnel exactly like a straight one. Cost, stated: a curved tunnel
  // paints its full route for one frame, the same extra pass `Trace`
  // already documents for curve length.
  const [measuredPoints, setMeasuredPoints] = useState<readonly Point[] | null>(null);
  // The callback in a ref so a caller passing an inline arrow does not make
  // the effect below re-fire on every render.
  const onGeometryRef = useRef(onGeometry);
  onGeometryRef.current = onGeometry;

  useLayoutEffect(() => {
    const host = hostRef.current;
    const line = host?.querySelector<SVGPathElement>('[data-slot="trace-line"]') ?? null;
    let resolved = geometry;
    if (geometry.points === null && line) {
      const total = line.getTotalLength();
      const sampled: Point[] = [];
      for (let i = 0; i <= curveSamples; i += 1) {
        const p = line.getPointAtLength((total * i) / curveSamples);
        sampled.push({ x: p.x, y: p.y });
      }
      resolved = { ...geometry, length: total, points: sampled };
      setMeasuredLength(total);
      setMeasuredPoints(sampled);
    } else {
      setMeasuredLength(null);
      setMeasuredPoints(null);
    }
    onGeometryRef.current?.(resolved);
  }, [geometry, curveSamples]);

  return (
    <g
      data-slot="trace-route"
      data-routing={geometry.routing}
      data-side-start={geometry.sides.start}
      data-side-end={geometry.sides.end}
      ref={hostRef}
      className={cn(className)}
      {...props}
    >
      <TraceBody
        id={id}
        path={geometry.path}
        length={measuredLength ?? geometry.length}
        points={geometry.points ?? measuredPoints ?? undefined}
        tunnel={tunnel}
        crossing={crossing}
        variant={variant}
        color={color}
        animated={animated}
        splitAtLabel={splitAtLabel}
        labelPosition={labelPosition}
        markerEnd={markerEnd}
        strokeWidth={strokeWidth}
        vectorEffect={vectorEffect}
        interactive={interactive}
        hitStrokePx={hitStrokePx}
        showHitRegion={showHitRegion}
        diagnostics={diagnostics}
        highlighterKind={highlighterKind}
      />
      {terminals ? (
        <>
          <TraceTerminal
            data-end="from"
            x={from.x}
            y={from.y}
            dir={from.dir}
            radius={terminalRadius}
            color={terminalColor}
            showDirection={showFromDirection}
          />
          <TraceTerminal
            data-end="to"
            x={to.x}
            y={to.y}
            dir={to.dir}
            radius={terminalRadius}
            color={terminalColor}
            showDirection={showToDirection}
          />
        </>
      ) : null}
    </g>
  );
}

"use client";

// src/components/traceBadge.tsx — NET-NEW (docs/TRACE-PLAN.md P4 · Lane D).
//
// Two halves with two different provenances, and that split is the whole
// reason this file is small:
//
//   - The MATH is ported, and already here. `fractionNearest` (project a
//     pointer onto the polyline, get its arc-length fraction),
//     `pointAtFraction` (the inverse) and `clampLabelPosition` (0.05..0.95)
//     live in `./trace.layout.ts`, ported by value from
//     `packages/bbox-ui/src/trace.layout.ts` (`b5b2778`), itself from
//     SystemSketch's `connectionPresentation.ts`. This file derives no
//     geometry of its own.
//   - The DOM is net-new, because there is nothing to port. SystemSketch has
//     no custom draggable edge label at all: its arrow labels are stock
//     tldraw `labelPosition` ("Stock, and draggable only by pointer",
//     `inspectorModel.ts:894-904`) and its custom connections carry only the
//     z-1 pill. What DOES exist there is the pill's drag MECHANISM —
//     `pillPosition: clampPillPosition(fractionNearest(points, handle))`
//     (`ConnectionShapeUtil.tsx:658`) — and this file is that one line, with
//     a real pointer gesture and a stock shadcn Badge around it.
//
// Zach's ask, verbatim: "we want the option to add a badge to the line (can
// use just the normal shadcn badge component we already have) and you should
// be able to drag the badge along the line to change its positioning... if
// you double click the line to add text, it will display inside of a badge."
// The double-click-to-CREATE half belongs to the host — that gesture lands on
// the trace's hit path (`trace.tsx`'s `interactive` prop), which this
// component knows nothing about. Everything from "a badge exists" onward is
// here.
//
// WHY DOM and not SVG: it renders the stock `Badge` (`./badge.tsx`) — Zach
// named it — which is a Tailwind-styled `<span>`. Wrapping it in a
// `<foreignObject>` to live inside the trace's `<svg>` would buy nothing and
// cost the badge its normal layout and text metrics. So the contract is: the
// badge is an absolutely-positioned sibling of the svg, and `points` are read
// in the coordinate space an absolutely-positioned child's `left`/`top`
// resolve against — its `offsetParent`'s padding box.
//
// UPDATED (docs/INVALID-STATES-PLAN.md D4, ruling 4): `t` widened from a
// plain fraction to `PathAddress` (./trace.layout.ts), the one address
// scheme shared with the new `TraceMark`. A plain number is unaffected —
// `resolvePathAddress` is the identity for anything already in `[0, 1]` —
// so this is additive, not a behaviour change.

import {
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type MouseEvent as ReactMouseEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

import { cn } from "../lib/utils";
import { Badge, type BadgeProps } from "./badge";
import { EditableText } from "./editableText";
import {
  LABEL_POSITION_DEFAULT,
  clampLabelPosition,
  fractionNearest,
  pointAtFraction,
  resolvePathAddress,
  type PathAddress,
  type Point,
} from "./trace.layout";

/** Font size inside the pill, in px. Matches the stock Badge's own `md` rung
 * (`text-xs` = 0.75rem = 12px) so the text at rest and the editing control
 * are the same size, and the pill does not resize on entering edit. */
export const TRACE_BADGE_FONT_PX = 12;

// WHY `ref` is omitted rather than forwarded: this component needs its own
// root node for `setPointerCapture` and for the `offsetParent` lookup that
// turns client coordinates into `points` space. Dropping a caller's `ref`
// silently would be a lie; merging two refs onto one node is machinery
// nothing here has asked for. A compile error is the honest third option.
export interface TraceBadgeProps extends Omit<ComponentProps<"div">, "ref" | "onChange" | "children"> {
  /**
   * The polyline the badge rides, in the coordinate space described in this
   * file's header. Passed in, never derived — that is what keeps this file
   * independent of HOW the trace was routed (straight, slanted, a curve
   * sampled at N points, an elbow staircase). `Trace`'s own `points` prop
   * (`trace.tsx:96`) exists to be handed straight to this.
   */
  points: readonly Point[];
  /**
   * The pill's position along the polyline (docs/INVALID-STATES-PLAN.md
   * D4 — one address scheme, shared with `TraceMark`, ./trace.layout.ts's
   * own module doc). A plain number is the arc-length fraction this prop
   * always accepted — resolving it through `resolvePathAddress` first is
   * the identity for anything already in `[0, 1]`, so no existing caller's
   * behaviour changes. `{px}` is accepted too, for symmetry with
   * `TraceMark`, though a draggable label has little use for it in
   * practice. The RESOLVED fraction is then clamped to 0.05..0.95 for
   * rendering exactly as before — a label sitting on a terminal reads as
   * part of the terminal rather than as a fact about the trace. `data-t`
   * reports the clamped value actually used.
   */
  t?: PathAddress;
  /** Controlled. Omit it and the badge is not draggable at all — that is the
   * gate, rather than a separate `draggable` prop that could disagree with
   * whether anyone is actually listening. Still emits a plain fraction, the
   * pill's own currency for a drag (arc-length projection, not an address). */
  onTChange?: (t: number) => void;
  value: string;
  onValueChange?: (value: string) => void;
  /** Controlled, like `EditableText.editing`. Omit `onEditingChange` and
   * double-click-to-edit is off — the same gate as `onTChange`. */
  editing?: boolean;
  onEditingChange?: (editing: boolean) => void;
  /** Passed through to the stock `Badge` untouched. */
  variant?: BadgeProps["variant"];
  size?: BadgeProps["size"];
  placeholder?: string;
  /**
   * Escape hatch for a host whose `points` are NOT in its own CSS pixel
   * space — a zoomed/panned canvas, where a screen point has to go through
   * the camera before it means anything to the route. The default is the
   * `offsetParent` conversion below, which is right for a plain
   * `position: relative` container (every story here, and React Flow's own
   * `EdgeLabelRenderer`).
   */
  toLocal?: (client: Point) => Point;
}

/**
 * Client (viewport) coordinates -> the space `points` live in.
 *
 * `offsetParent` is not a guess: it is, by CSS definition, the element an
 * absolutely-positioned child's `left`/`top` are measured against — so it is
 * exactly the frame `pointAtFraction`'s output is already being written into.
 * Using it closes the round trip (point -> css -> pointer -> point) without
 * the caller having to hand over a container ref it would then have to keep
 * in sync.
 *
 * Three corrections, each for a real case: `clientLeft`/`clientTop` because
 * `getBoundingClientRect` measures the BORDER box while `left` resolves
 * against the padding box; `scrollLeft`/`scrollTop` because a scrolled
 * container moves its children without moving its own rect; and the
 * rect-to-offset ratio because a CSS-transformed ancestor scales the rect but
 * not the layout coordinates.
 */
function clientToLocal(root: HTMLElement, client: Point): Point {
  const parent = root.offsetParent as HTMLElement | null;
  if (!parent) return client;
  const rect = parent.getBoundingClientRect();
  const scaleX = parent.offsetWidth > 0 ? rect.width / parent.offsetWidth : 1;
  const scaleY = parent.offsetHeight > 0 ? rect.height / parent.offsetHeight : 1;
  return {
    x: (client.x - rect.left) / (scaleX || 1) - parent.clientLeft + parent.scrollLeft,
    y: (client.y - rect.top) / (scaleY || 1) - parent.clientTop + parent.scrollTop,
  };
}

export function TraceBadge({
  points,
  t = LABEL_POSITION_DEFAULT,
  onTChange,
  value,
  onValueChange,
  editing = false,
  onEditingChange,
  variant = "secondary",
  size,
  placeholder,
  toLocal,
  className,
  style,
  onPointerDown,
  onDoubleClick,
  ...props
}: TraceBadgeProps) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [dragPointerId, setDragPointerId] = useState<number | null>(null);

  const effectiveT = clampLabelPosition(resolvePathAddress(points, t));
  const anchor = pointAtFraction(points, effectiveT);
  const canDrag = Boolean(onTChange);
  const canEdit = Boolean(onEditingChange);
  const dragging = dragPointerId !== null;

  // WHY a per-render "latest" box instead of naming these in the effect's
  // deps: the drag listeners below must always read the CURRENT `points` and
  // `onTChange` (the host re-renders on every pointermove, so a closure
  // captured at pointerdown is stale one frame later), but putting them in a
  // dep array would tear down and re-add three window listeners on every
  // frame of the drag. One mutable box gives fresh reads with a subscription
  // that lives exactly as long as the gesture.
  const latest = useRef({ points, onTChange, toLocal });
  latest.current = { points, onTChange, toLocal };

  useEffect(() => {
    if (dragPointerId === null) return;
    const root = rootRef.current;
    if (!root) return;

    const handleMove = (event: PointerEvent) => {
      if (event.pointerId !== dragPointerId) return;
      const node = rootRef.current;
      if (!node) return;
      const client = { x: event.clientX, y: event.clientY };
      const { points: livePoints, onTChange: emit, toLocal: convert } = latest.current;
      const local = convert ? convert(client) : clientToLocal(node, client);
      // The donor's one line, unchanged in meaning:
      //   pillPosition = clampPillPosition(fractionNearest(points, handle))
      // Nearest-point PROJECTION, not a pointer delta — so the badge tracks
      // the path rather than the finger, and a pointer that wanders off the
      // line still puts the badge back ON it. Rejected alternative: keeping
      // the grab offset (where you grabbed the pill stays under the pointer).
      // It reads nicer for one frame and then drifts, because an offset that
      // is constant in screen space is not constant in arc length once the
      // route bends.
      emit?.(clampLabelPosition(fractionNearest(livePoints, local)));
    };
    const handleEnd = (event: PointerEvent) => {
      if (event.pointerId !== dragPointerId) return;
      setDragPointerId(null);
    };

    // WHY window listeners and not React's own `onPointerMove` on the root,
    // given `setPointerCapture` is already held: capture is best-effort here
    // (see the pointerdown handler), and a drag whose only move listener sits
    // on the badge would silently stop tracking the instant capture is
    // unavailable and the pointer leaves the pill. `window` is correct with
    // OR without capture — captured events still bubble there — so the
    // gesture has one code path instead of two that can disagree.
    window.addEventListener("pointermove", handleMove);
    window.addEventListener("pointerup", handleEnd);
    window.addEventListener("pointercancel", handleEnd);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      window.removeEventListener("pointerup", handleEnd);
      window.removeEventListener("pointercancel", handleEnd);
      if (root.hasPointerCapture(dragPointerId)) root.releasePointerCapture(dragPointerId);
    };
  }, [dragPointerId]);

  const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event);
    if (event.defaultPrevented) return;
    // WHY a drag never starts while `editing`: pressing the pill would blur
    // the input, and EditableText commits on blur — so a nudge of the badge
    // would silently end text entry mid-word. Escape or Enter first, then
    // drag.
    if (!canDrag || editing || event.button !== 0) return;
    const root = rootRef.current;
    if (!root) return;
    // The badge sits ON TOP of the trace's hit path. Without this, a grab
    // also reads as a press on the line underneath, and the host's
    // double-click-to-create fires on a double-grab of an existing badge.
    event.stopPropagation();
    try {
      root.setPointerCapture(event.pointerId);
    } catch {
      // Best-effort. `setPointerCapture` throws NotFoundError for a
      // pointerId the browser has no ACTIVE pointer for — exactly the case
      // for a synthetic `PointerEvent` dispatched by a play function. The
      // gesture does not depend on it (see the window listeners above); it is
      // here so a REAL pointer leaving the pill keeps hover/`:active` on the
      // pill instead of flickering across whatever it passes over.
    }
    setDragPointerId(event.pointerId);
  };

  const handleDoubleClick = (event: ReactMouseEvent<HTMLDivElement>) => {
    onDoubleClick?.(event);
    if (event.defaultPrevented || !canEdit) return;
    event.stopPropagation();
    onEditingChange?.(true);
  };

  return (
    <div
      data-slot="trace-badge"
      data-t={effectiveT}
      data-dragging={dragging || undefined}
      data-editing={editing || undefined}
      ref={rootRef}
      className={cn(className)}
      style={{
        // WHY `position` is inline and not Tailwind's `absolute`: this is
        // load-bearing GEOMETRY, not decoration. Tailwind v4 only generates
        // utilities it finds by scanning configured sources, and this repo
        // has already been bitten once by a utility used only from an
        // unscanned directory silently never being emitted (`CLAUDE.md`,
        // "Tailwind v4 only scans the app's own sources"). A badge that
        // quietly falls back to `position: static` would sit at the end of
        // the flow instead of on the line.
        position: "absolute",
        left: anchor.x,
        top: anchor.y,
        transform: "translate(-50%, -50%)",
        // `touch-action: none` is what makes a touch drag reach pointermove
        // at all rather than being consumed as a scroll; `user-select: none`
        // stops a drag across the pill painting a text selection.
        touchAction: "none",
        userSelect: "none",
        cursor: canDrag ? (dragging ? "grabbing" : "grab") : undefined,
        ...style,
      }}
      onPointerDown={handlePointerDown}
      onDoubleClick={handleDoubleClick}
      {...props}
    >
      {/* WHY neither of these gets a `data-slot` of its own, despite the
          house rule: both already emit one (`badge`, `editable-text`) and
          both spread caller props AFTER it, so passing one here would
          OVERWRITE the stock slot rather than add to it — erasing the very
          evidence that this is the stock shadcn Badge with the stock
          EditableText inside it. The wrapper above carries this component's
          slot; these two carry theirs. */}
      <Badge variant={variant} size={size}>
        <EditableText
          size="custom"
          sizePx={TRACE_BADGE_FONT_PX}
          lines="single"
          editing={editing}
          placeholder={placeholder}
          onChange={onValueChange}
          onCommit={(next) => {
            onValueChange?.(next);
            onEditingChange?.(false);
          }}
          onCancel={() => onEditingChange?.(false)}
          // Inherit the pill's own colour instead of EditableText's default,
          // so `variant` stays the single place the look is decided.
          style={{ color: "inherit" }}
        >
          {value}
        </EditableText>
      </Badge>
    </div>
  );
}

"use client";

// src/components/traceTerminal.tsx — NET-NEW (docs/TRACE-PLAN.md P1). Not a
// port: neither `packages/bbox-ui` nor SystemSketch has a terminal glyph.
//
// WHY this exists at all, and why it is NOT a `Port`: Zach's explicit
// reversal — "Let's not use real ports. We can just draw a circle with an
// arrow inside that shows the polarity... they just take an xy position and
// a polarity, and input/output direction." These are ILLUSTRATION props for
// the trace galleries, so nothing here imports `port.tsx`, and a real board
// would mount a real `Port` instead. Keeping them separate is what stops a
// story fixture from quietly becoming a second, competing port component.
//
// WHY `{x, y, dir}` and no polarity prop: (face, polarity) -> flow tangent
// is 2-to-1, so the eight pairs quotient to four glyphs — Zach's own
// correction, "really 4 options not 8 because top input is the same as
// bottom output." The full argument, and the `side(from)`/`side(to)`
// derivation that keeps the ROUTE knowing which end is which, live on
// `TraceDir` in `./trace.layout.ts`. The arrowhead that distinguishes the
// ends is painted by the trace (`markerEnd` at the `to` end), never here.

import { type ComponentProps, type CSSProperties } from "react";

import { cn } from "../lib/utils";
import { DIR_ROTATION, type TraceDir } from "./trace.layout";

/** The glyph's ring radius in user units. 9 keeps it a touch smaller than
 * `Port`'s `md` dot so a terminal never reads as a port. */
export const TRACE_TERMINAL_RADIUS = 9;
export const TRACE_TERMINAL_RING_PX = 2;

/**
 * The arrow inside the ring, authored pointing +x (i.e. `dir: "right"`) and
 * rotated by `DIR_ROTATION`. Expressed as fractions of the radius so the
 * glyph scales as one piece.
 *
 * The tail deliberately stops SHORT of where the tip reaches (0.40r behind
 * the centre vs 0.50r ahead) for LEGIBILITY ONLY: at an 18px ring a shaft
 * centred on the disc reads as a plus sign, and the short tail biases the
 * whole mark forward so it reads as travelling.
 *
 * It is NOT what makes the glyph measurably directional — mutation-testing
 * this (2026-09-17, tail 0.40r -> 0.50r) left `Trace.stories.tsx` green,
 * because the HEAD alone already pulls the arc-length centroid ~1.4px onto
 * the `dir` side. The head is the load-bearing part of that measurement;
 * deleting it drops the centroid offset under the story's 1px floor and
 * turns the suite red. Recorded so a future tidy-up does not "simplify" the
 * head away on the theory that the shaft carries the direction.
 */
function arrowPath(radius: number): string {
  const tail = -0.4 * radius;
  const tip = 0.5 * radius;
  const barbX = 0.075 * radius;
  const barbY = 0.36 * radius;
  return `M ${tail} 0 L ${tip} 0 M ${barbX} ${-barbY} L ${tip} 0 L ${barbX} ${barbY}`;
}

export interface TraceTerminalProps extends Omit<ComponentProps<"g">, "x" | "y"> {
  x: number;
  y: number;
  /** The flow tangent — the direction data travels THROUGH this point.
   * NOT a face and NOT a polarity; see `TraceDir`. */
  dir: TraceDir;
  radius?: number;
  /** Any CSS colour. Defaults to the accent `Port` already uses for
   * `wired` (docs/TRACE-PLAN.md D8: the screenshot's amber IS this repo's
   * orange, so no new token). */
  color?: string;
  /** What fills the disc. Opaque on purpose — an opaque disc hides the
   * trace's own stroke running underneath it, so the line reads as
   * arriving AT the terminal rather than through it. */
  fill?: string;
  /**
   * Draw the arrow that claims this end's flow tangent. Defaults to
   * `true` so every existing caller is unaffected.
   *
   * WHY this exists: `dir` is a fact about the TERMINAL — it is always
   * well-defined — but the arrow is a claim about the ROUTE, namely that
   * the painted path actually leaves or arrives along it. `straight` and
   * `slanted` don't honor that claim at every end (`TRACE_ROUTING_TANGENTS`
   * / `routingTangents` in `trace.routing.ts` — the fidelity is per END and
   * per ROUTING, not a blanket "these two kinds never show polarity": a
   * `slanted` trace honors its SOURCE and is blind only at its target). A
   * caller whose routing doesn't read this end's `dir` passes `false`
   * rather than let the glyph assert a polarity the geometry ignores —
   * this was Zach's own correction on the `TracePolarity` gallery, which
   * drew an arrow on every terminal regardless of whether anything
   * downstream ever looked at it.
   *
   * The ring's radius and centre never move when this is `false` — only
   * the arrow `<path>` is omitted — so a blind and an honored terminal
   * still line up size-for-size in a gallery row.
   */
  showDirection?: boolean;
}

/**
 * An SVG `<g>` — mount it inside an `<svg>`, positioned by its own
 * `x`/`y`, not by CSS. Renders nothing interactive: no pointer handlers, no
 * hit halo, no state. A story that wants a terminal to be draggable adds
 * that itself.
 */
export function TraceTerminal({
  x,
  y,
  dir,
  radius = TRACE_TERMINAL_RADIUS,
  color = "var(--bbox-primary, var(--primary))",
  fill = "var(--card)",
  showDirection = true,
  className,
  ...props
}: TraceTerminalProps) {
  // WHY this glyph's drawn twin now lives at the boundary, not here
  // (docs/peps/0001-sketch-skin-at-the-boundary.md M5b): before this
  // migration, `SketchOutline` couldn't be used — it assumes HTML/CSS
  // positioning (`position: absolute` against a `position: relative`
  // ancestor) and this glyph is pure SVG, positioned by its own `<g
  // transform>` — so this hand-rolled the same crisp/sketch pair
  // `trace.tsx`'s own `TraceBody` used to. The boundary has no such
  // problem: `sketchAtEdge.ts` appends a twin `<svg>` into THIS `<g>`
  // (added to `DOT_SELECTOR`), which already inherits the `translate`/
  // `rotate` transform above — the hand-rolled duplicate existed only
  // because the core's own abstraction could not reach this case. The
  // circle's fill still always paints (an opaque disc, never sketched —
  // see this file's own `fill` doc); only its stroke is suppressed, now
  // by the boundary's own crisp-suppression CSS rather than a per-skin
  // `display` switch on a twin this file drew itself.
  return (
    <g
      data-slot="trace-terminal"
      data-dir={dir}
      transform={`translate(${x} ${y}) rotate(${DIR_ROTATION[dir]})`}
      className={cn(className)}
      // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M6. `color` is
      // this glyph's own STATE-owned colour (the caller's prop, same split
      // `portRingColor` makes), published here so a boundary sketch pass
      // can draw the ring in the right colour without reading a
      // `stroke`/`border-color` the skin has already blanked.
      style={{ "--bbox-ink-state": color } as CSSProperties}
      {...props}
    >
      <circle
        data-slot="trace-terminal-ring"
        cx={0}
        cy={0}
        r={radius}
        fill={fill}
        // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M7. This
        // component's own seed (`trace-terminal:${dir}:${radius}`),
        // published on the RING ITSELF rather than the parent `<g>` the
        // plan's table names — `sketchAtEdge.ts`'s RING_SELECTOR loop
        // reads `data-bbox-seed` off the circle it measures, matching
        // where the M5b build deviation (see the build report) actually
        // reads geometry from.
        data-bbox-seed={`trace-terminal:${dir}:${radius}`}
        // WHY `--bbox-skin-line-override` stays (deviation from the
        // migration plan's literal table, which said to drop it — see the
        // build report): dropping it would leave the crisp ring visible
        // forever, even under the sketch skin. Block/Badge/PortEdge all
        // keep the identical read for the identical reason — this token is
        // the UNCHANGED, token-layer mechanism (docs/peps/0001's own "token
        // styling stays exactly as it is") that blanks a state-owned line
        // to transparent under sketch, and it is the only way to hide just
        // the STROKE while the circle's opaque `fill` keeps painting; a
        // `display:none` on the whole element (the mechanism `trace-line`
        // uses) would hide the fill too.
        style={{ stroke: `var(--bbox-skin-line-override, ${color})` }}
        strokeWidth={TRACE_TERMINAL_RING_PX}
      />
      {showDirection ? (
        <path
          data-slot="trace-terminal-arrow"
          d={arrowPath(radius)}
          fill="none"
          stroke={color}
          strokeWidth={Math.max(1, radius * 0.2)}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      ) : null}
    </g>
  );
}

