import { pointAtFraction, polylineLength, type Point } from "./trace.layout";

/**
 * PORTED VERBATIM (`tunnelEdge.ts:1-9`), because it is the clearest
 * statement of what a tunnel IS that exists anywhere:
 *
 * A tunnel is still one ordinary connection. Only its idle presentation
 * changes: the long run leaves the surface while a short stub and outlined
 * via remain at both endpoints. Hover and selection preview the complete run
 * without removing those mouths; focusing a layer reveals only that layer and
 * tunnels every other semantic edge.
 */

/** Visible cable between a port and its tunnel via, in page units.
 *  PORTED (`tunnelEdge.ts:16`). */
export const TUNNEL_STUB_LENGTH = 34;

/** Two readable stubs plus a real hidden middle. Shorter cables stay visible.
 *  PORTED (`tunnelEdge.ts:19`). */
export const TUNNEL_MIN_PATH_LENGTH = TUNNEL_STUB_LENGTH * 2 + 16;

/**
 * ADDED (pyblocks `index.css:566-570` + `ConnectionShapeUtil.tsx:966`):
 * the via dot's radius. The donor left this in a stylesheet; here it is a
 * number so `TraceBody` can emit it and a test can measure it.
 */
export const TUNNEL_VIA_RADIUS = 4;

/** PORTED (`tunnelEdge.ts:21`). */
export type TunnelDisplayState = "off" | "hidden" | "preview" | "revealed";

/**
 * PORTED (`tunnelEdge.ts:23-28`).
 *
 * WHY every field is an ARGUMENT rather than something this module reads:
 * `focusedLayer` and `contextFocused` are INTERACTION state, which
 * `ARCHITECTURE.md` makes host-owned ("interaction geometry is host-owned
 * and never travels"). Taking them as parameters is what lets this stay a
 * pure function in the `components` kit — it never learns whether "focused"
 * meant a tldraw selection, a React Flow `selected` flag or a story's
 * `useState`. The donor's own split agrees: membership (`props.tunnel`,
 * `props.tunnelLayer`) lives on the document, focus lives in a view-local
 * atom that "never mutates or dirties the board" (`tunnelLayers.ts:17`).
 */
export interface TunnelDisplayContext {
  /** Is this edge configured as a tunnel at all? Document data. */
  enabled: boolean;
  /** Which layer this edge is on. Document data. `''` means none. */
  layer: string;
  /** Which layer the VIEW is focused on, or null. Host state. */
  focusedLayer: string | null;
  /** Hovered or selected — this edge is the one the pointer is about.
   *  Host state. */
  contextFocused: boolean;
}

/**
 * Resolve the four paint states without changing the semantic connection.
 * Hover/selection previews the complete route but keeps its tunnel mouths.
 * A focused layer alone removes its own mouths and tunnels every other edge.
 *
 * PORTED VERBATIM including this docstring (`tunnelEdge.ts:30-44`). The
 * branch order is load-bearing and is the donor's: a focused layer outranks
 * `enabled`, which is what makes layer focus able to tunnel edges that were
 * never configured as tunnels — the "reveals it and tunnels other edges"
 * half of the feature.
 */
export function tunnelDisplayState(context: TunnelDisplayContext): TunnelDisplayState {
  if (context.focusedLayer) {
    if (context.layer === context.focusedLayer) return "revealed";
    return context.contextFocused ? "preview" : "hidden";
  }
  if (!context.enabled) return "off";
  return context.contextFocused ? "preview" : "hidden";
}

/**
 * Does this display state hide the long run? `hidden` only.
 *
 * ADDED — the donor's renderers spell this inline as
 * `state === 'hidden'` (and pyblocks as the truthiness of `tunnelVisual`).
 * Named here because three call sites need it and because `preview` being
 * NOT-hidden is the single most confusable thing about this feature:
 * preview draws the whole route AND keeps the mouths.
 */
export function tunnelHidesRun(state: TunnelDisplayState): boolean {
  return state === "hidden";
}

/**
 * Does this display state paint the two via dots?
 *
 * ADDED, same reason. `off` and `revealed` have no mouths to mark; `hidden`
 * and `preview` both do — that is the donor's stated contract ("Hover and
 * selection preview the complete run WITHOUT REMOVING those mouths").
 */
export function tunnelShowsVias(state: TunnelDisplayState): boolean {
  return state === "hidden" || state === "preview";
}

/** PORTED (`tunnelEdge.ts:46-51`). */
export interface TunnelPathPresentation {
  /** SVG dash pattern that draws `stub / hidden middle / stub`. */
  dashArray: string;
  /** Arc-length positions of the two visible via dots. */
  viaDistances: readonly [number, number];
}

/**
 * `null` means the route should remain fully visible.
 *
 * PORTED VERBATIM (`tunnelEdge.ts:53-68`).
 *
 * NOTE this repo's own renderer does NOT use `dashArray` — see
 * `tunnelMouths` for why, and this file's header for the collision. It is
 * kept, exported and tested because (a) it is the donor's public contract
 * and the donor's tests are this port's independent oracle, and (b) it
 * remains the right answer for a host that paints one path and has no
 * variant dash to protect. `viaDistances` IS used, by `tunnelMouths`.
 */
export function tunnelPathPresentation(
  pathLength: number,
  revealed: boolean,
): TunnelPathPresentation | null {
  if (revealed || !Number.isFinite(pathLength) || pathLength <= TUNNEL_MIN_PATH_LENGTH) {
    return null;
  }
  const hiddenMiddle = pathLength - TUNNEL_STUB_LENGTH * 2;
  return {
    dashArray: `${TUNNEL_STUB_LENGTH} ${hiddenMiddle} ${TUNNEL_STUB_LENGTH} 0`,
    viaDistances: [TUNNEL_STUB_LENGTH, pathLength - TUNNEL_STUB_LENGTH],
  };
}

/** PORTED (`tunnelEdge.ts:70-74`). See this file's header, change (2), on
 *  the donor's own `startVia`/`start` drift. */
export interface TunnelVisual extends TunnelPathPresentation {
  startVia: Point;
  endVia: Point;
}

/**
 * Resolve the idle stubs and vias on the same routed points the cable paints.
 *
 * PORTED VERBATIM (`tunnelEdge.ts:76-84`).
 */
export function tunnelVisualForPoints(
  points: readonly Point[],
  revealed: boolean,
): TunnelVisual | null {
  const length = polylineLength(points);
  const presentation = tunnelPathPresentation(length, revealed);
  if (!presentation) return null;
  const [startDistance, endDistance] = presentation.viaDistances;
  return {
    ...presentation,
    startVia: pointAtFraction(points, startDistance / length),
    endVia: pointAtFraction(points, endDistance / length),
  };
}

/* ==========================================================================
 * ADDED — the drawn geometry of a tunnel. Nothing below is a port.
 * ========================================================================== */

/**
 * The sub-polyline between two arc-length positions, interior vertices kept.
 *
 * ADDED. Built on the ported `pointAtFraction`/`polylineLength` so a mouth
 * lands on exactly the point the donor's via lands on — the two cannot
 * drift, because the via and the mouth's far end are THE SAME CALL.
 */
function polylineSlice(points: readonly Point[], fromDistance: number, toDistance: number): Point[] {
  const total = polylineLength(points);
  if (total <= 0 || points.length < 2) return points.length ? [points[0]] : [];
  const from = Math.max(0, Math.min(fromDistance, total));
  const to = Math.max(from, Math.min(toDistance, total));
  const sliced: Point[] = [pointAtFraction(points, from / total)];
  let travelled = 0;
  for (let index = 1; index < points.length; index += 1) {
    travelled += Math.hypot(
      points[index].x - points[index - 1].x,
      points[index].y - points[index - 1].y,
    );
    // Strictly inside: a vertex sitting exactly on a cut would duplicate
    // the endpoint `pointAtFraction` already produced.
    if (travelled > from && travelled < to) sliced.push(points[index]);
  }
  sliced.push(pointAtFraction(points, to / total));
  return sliced;
}

/** ADDED. The two drawn stubs, plus the vias that terminate them. */
export interface TunnelMouths {
  /** Polyline from the source endpoint to the first via. */
  start: Point[];
  /** Polyline from the second via to the target endpoint. */
  end: Point[];
  startVia: Point;
  endVia: Point;
}

/**
 * The two stubs as REAL POLYLINES, for a renderer that shortens its `d`.
 *
 * WHY this exists rather than just using the donor's `dashArray` — the one
 * deliberate deviation in this port, so it is argued in full:
 *
 *   1. **The dash channel is already occupied here.** `traceStrokeStyle`
 *      (trace.tsx) puts `ASYNC_PACKET_DASHARRAY` on an `async` trace, a
 *      dot pattern on `delayed`, and `DATA_MARCH_DASHARRAY` on an animated
 *      one. An SVG path has exactly one `stroke-dasharray`. Painting the
 *      tunnel with it means a tunnelled async cable silently stops looking
 *      async. Both donors hit this and both lost the same way: pyblocks
 *      `ConnectionShapeUtil.tsx:958-963` is a ternary that drops the
 *      `pinned` dash the moment a tunnel is active. That is not a bug in
 *      the donor — it is what the dash technique costs, paid somewhere
 *      else.
 *   2. **The sketch skin rewrites the path.** The boundary pass's
 *      `sketchTraceD` (`src/skin/sketchAtEdge.ts`, formerly this file's own
 *      `sketchedTracePath` before docs/peps/0001-sketch-skin-at-the-
 *      boundary.md moved it to the edge) jitters interior points, which
 *      CHANGES the arc length; a dash pattern computed from the crisp
 *      length lands in the wrong place on the drawn twin. Slicing geometry
 *      first and sketching each mouth separately is correct by
 *      construction — `flattenPathData` already treats each `M` as a new
 *      run.
 *   3. **It makes the claim measurable.** A dashed tunnel's `d` is
 *      byte-identical to an untunnelled one, so "the long run is hidden"
 *      can only be asserted from a prop. A shortened `d` is measurable on
 *      the mounted element (`getTotalLength()`), which is the difference
 *      between a test and a restatement.
 *
 * What it costs, stated honestly: the renderer needs the route's POINTS,
 * not just its `d`. For `curved` routing those only exist after layout
 * (`Trace` samples them off the mounted path), so a curved tunnel paints
 * its full route for exactly one frame before the mouths appear — the same
 * one-frame cost `Trace` already documents for curve length measurement.
 *
 * Returns `null` on the same conditions as `tunnelPathPresentation`:
 * revealed, non-finite, or too short to have a middle worth hiding.
 */
export function tunnelMouths(points: readonly Point[], revealed: boolean): TunnelMouths | null {
  const visual = tunnelVisualForPoints(points, revealed);
  if (!visual) return null;
  const [startDistance, endDistance] = visual.viaDistances;
  const total = polylineLength(points);
  return {
    start: polylineSlice(points, 0, startDistance),
    end: polylineSlice(points, endDistance, total),
    startVia: visual.startVia,
    endVia: visual.endVia,
  };
}

"use client";

// src/components/wireLayer.tsx — `WireLayer`: paints a `Wire[]` as `Trace`s
// between two Blocks' real, measured Port dots (docs/BLOCK-PORT-EDGES-PLAN.md
// §5, phase B1). `WireLayerProps` is the frozen contract the plan declared
// before this file existed, so B2's async gallery could code against it
// while this lane was still building it.
//
// WireLayer never invents a point. It resolves each `WireEnd` to a rendered
// dot — `[data-port-id]` inside `[data-block-id]`, falling back to a
// collapsed stand-in dot whose `data-collapsed-ports` names the id (the same
// dot a Block flips to in simple view — no wire data changes, only
// measurement) — reads its centre with `getBoundingClientRect` (app-level
// measurement, the same D8 legality `blockPort.tsx`'s own band-measuring
// already relies on), and hands the two points to `Trace`. An end that
// cannot be found — a wire into a child whose block is not expanded — is
// skipped, not guessed at, and its wire id is stamped onto the layer's own
// `data-unresolved-wires`, matching the donor's rule that only expanded
// blocks can show children.
//
// WHY the layer paints ABOVE every Block (D-B1, reversing the donor's
// `keepConnectionsAtBottom`): a wire attaches to a dot that already sits on
// a wall painting above the block's own card (`blockPort.tsx`'s own D-B1
// note) — a wire painting under the block would have its whole approach to
// that dot swallowed by the card. `pointer-events: none` on the SVG root
// keeps the layer from stealing drag/click from anything under it; `Trace`'s
// own `interactive` hit path is exactly the opt-back-in a host that wants
// one would reach for, left off here on purpose.
//
// ADDED (2026-09-19, lane `fix-edges`): the layer RESOLVES each wire's
// routing against `DEFAULT_TRACE_ROUTING` (`elbow`) instead of forwarding
// `undefined`, and it no longer applies `fanWires`' perpendicular spread to
// anything. Both are Zach's 2026-09-19 ruling — "by default elbow arrows
// should always be used" and "the port only should have 1 connection point
// in the center" — and both are asserted in `EdgeDefaults.stories.tsx`.
//
// ADDED (docs/CONTROL-FLOW-PLAN.md lane D): keep-outs and badges. For a
// wire whose `routing` is `"elbow"`, the layer measures every structural box
// in the fixture once per pass — a region's frame, an arm's row, a block's
// card — and hands the router the ones this wire is NOT part of, which is
// Zach's rule ("data cables that aren't flowing through the branch should
// actively avoid the branch — bypass by going above or below it") turned
// into two numbers per box. Nothing else changes: a wire with any other
// routing is handed exactly the props it was handed before this landed, and
// the badge sibling below is not rendered at all when no wire carries one.
//
// WHY the layer, and not the story, collects the obstacles: `elbow/` is a
// verbatim port whose donor read live tldraw shapes and deliberately left
// its collector behind (`elbow/traceContract.ts`: "there is no obstacle
// COLLECTOR here, by design"). The collector belongs wherever the real
// boxes are measured, and that is here — the one place that already reads
// the rendered DOM and already owns the container's coordinate space.
//
// WHY there is no polarity prop anywhere here (the plan's "8-vs-4"
// resolution): a rail's own `data-edge` attribute already says everything a
// terminal spec needs, because `BlockSide` ("top"|"right"|"bottom"|"left")
// is already the exact same union as `TraceDir` — `from` leaves along the
// FROM port's own wall, `to` arrives travelling AGAINST the TO port's wall
// (`OPPOSITE_DIR`).
import { useCallback, useLayoutEffect, useRef, useState, type RefObject } from "react";

import type { ElbowRect } from "./elbow/index";
import type { BlockSide } from "./port.layout";
import { portDotRingRadiusPx, usePortVariant } from "../skin/portVariants";
import { Trace, traceLinecapOf, traceRingGapPx, traceRouteEnd, traceRouteStart } from "./trace";
import { TraceBadge } from "./traceBadge";
import { DEFAULT_TRACE_ROUTING, OPPOSITE_DIR, type Point, type TraceDir, type TraceRouting, type TraceTerminalSpec } from "./trace.layout";
import { keepOutsFor, type KeepOutRect, type Wire, type WireEnd } from "./wiring";

/* ------------------------------------------------------------------ */
/* The frozen surface (plan §5)                                        */
/* ------------------------------------------------------------------ */

export interface WireLayerProps {
  wires: Wire[];
  /** The fixture element whose coordinate space the layer fills; the layer
   *  is an absolutely-positioned SVG inset 0 inside it, rendered LAST. */
  containerRef: RefObject<HTMLElement | null>;
  /** Re-measure signal — bump when items/views change. */
  layoutKey?: unknown;
  /**
   * The polyline each wire was DRAWN on, in the container's space, reported
   * by `Trace` itself (sampled for a curve) — the geometry this layer
   * already reads back for its pills, handed on. Added for the region views'
   * wall-crossing markers (`blockRegion.crossings.ts`'s `wallCrossings`): one
   * derivation of where a cable runs, read back, never re-routed by the
   * caller. Called only when a wire's route actually moved.
   *
   * `null` when a wire this layer had reported STOPS being drawn — it went
   * unresolved (an end lost its dot) or left `wires` altogether. A caller
   * that caches polylines by id must drop the entry: otherwise a derived
   * mark (a wall-crossing circle) freezes on a path nobody paints any more
   * (audit of 7fbf22c, 2026-09-22).
   */
  onWireGeometry?(wireId: string, points: readonly Point[] | null): void;
}

/* ------------------------------------------------------------------ */
/* Resolving a WireEnd to a dot, and a dot to a terminal spec           */
/* ------------------------------------------------------------------ */

/** `[data-port-id]` inside `[data-block-id]` first; a collapsed stand-in dot
 *  whose `data-collapsed-ports` list contains the id otherwise. Both
 *  attributes are stamped by `blockPort.tsx`'s rail fill, never by this
 *  file — `WireLayer` only reads DOM another component already wrote.
 *
 *  WHY every candidate is ownership-checked (`closest("[data-block-id]")
 *  === block`) instead of taking `block.querySelector`'s first match: a
 *  MEMBER rendered inside an expanded Block stamps its own nested
 *  `[data-block-id]`, and a member can legally reuse a port id its parent
 *  also has (`proc`'s own `in` and its member `kid`'s own `in`, both valid,
 *  both distinct dots). A bare descendant query has no way to prefer the
 *  block's OWN dot over a member's, and resolves to whichever is first in
 *  document order — silently wrong, not unresolved, so nothing here ever
 *  flagged it. `reactFlowHost.tsx`'s `dotOwnedBy` already reads this
 *  correctly (nearest `data-block-id` ancestor decides); this is the same
 *  rule, so the two hosts' resolution genuinely agrees, matching what that
 *  file's own comment already claimed. Measured 2026-09-18: an edge into
 *  `proc/in` painted onto `kid`'s dot instead, with
 *  `data-unresolved-wires` still reading `""` — see
 *  `WireLayerOwnership.stories.tsx`. */
function resolveDot(container: HTMLElement, end: WireEnd): HTMLElement | null {
  const block = container.querySelector<HTMLElement>(`[data-block-id="${end.blockId}"]`);
  if (!block) return null;
  for (const candidate of block.querySelectorAll<HTMLElement>(`[data-port-id="${end.portId}"]`)) {
    if (candidate.closest("[data-block-id]") === block) return candidate;
  }
  for (const collapsed of block.querySelectorAll<HTMLElement>("[data-collapsed-ports]")) {
    if (collapsed.closest("[data-block-id]") !== block) continue;
    const members = (collapsed.getAttribute("data-collapsed-ports") ?? "").split(",").map((id) => id.trim());
    if (members.includes(end.portId)) return collapsed;
  }
  return null;
}

/** The `BlockSide` a resolved dot's own rail is mounted on. A straight read,
 *  not a lookup table — `BlockSide` and `TraceDir` are already the same four
 *  strings, so the rail's own `data-edge` attribute IS the face normal. */
function railEdgeOf(dot: HTMLElement): BlockSide | null {
  const edge = dot.closest<HTMLElement>('[data-slot="block-port-rail"]')?.getAttribute("data-edge");
  return edge === "top" || edge === "right" || edge === "bottom" || edge === "left" ? edge : null;
}

/** The painted dot a resolved end draws — the `[data-slot="port-dot"]`
 *  inside a labelled rail item, or the resolved element itself when it IS
 *  the dot (a collapsed stand-in wraps a bare `Port`, so it has one too). */
function paintedDotOf(resolved: HTMLElement): Element {
  return resolved.querySelector('[data-slot="port-dot"]') ?? resolved;
}

/**
 * The coordinate space every measured point and box is expressed in: the
 * client-px origin to subtract, then the scale to divide back out.
 *
 * WHY a scale at all: the React Flow host routes its edges through this
 * same file (`resolveWires`, below) and its nodes sit under the viewport's
 * `scale(zoom)` transform, so a client-px box there is `zoom` times the
 * flow-space box its edge is drawn in. Dividing the zoom out HERE is what
 * lets both hosts share one derivation instead of the React Flow host
 * re-deriving routes it does not own. The layer's OWN space reads its scale
 * off the DOM too (`containerSpace` / `scaleOf`, below), so a host that puts
 * a camera on the container gets correct cables without telling the layer.
 * At `scale: 1` every division is the identity, so an untransformed
 * container's numbers are exactly the numbers it produced before this
 * existed.
 */
export interface WireSpace {
  left: number;
  top: number;
  scale: number;
}

/**
 * The container's own rendered scale, read off the DOM rather than taken as a
 * prop — a host that zooms its canvas should not also have to tell this layer
 * about it, and `WireLayer` already measures everything else it uses.
 * Ported from claude/notebook-lab-work-order-472c22 `27b4314` ("A camera for
 * the board"), where the notebook lab's camera put a `transform: scale(z)` on
 * the board and every cable came back `z` times too long: `getBoundingClientRect`
 * answers in screen px while the `<svg>` inside the container draws in its
 * pre-transform user units.
 *
 * `offsetWidth` is the layout width, untouched by any ancestor transform;
 * `getBoundingClientRect().width` is that same box after every transform. The
 * ratio is therefore the accumulated scale — the same rect-to-offsetWidth
 * reading `reactFlowHost.tsx`'s `flowSpaceOf` uses for its viewport.
 * `offsetWidth` is an integer, so the ratio carries up to half a pixel of
 * rounding — snapped to exactly 1 when it is within half a percent, so the
 * untransformed case (every caller before this existed) keeps measuring
 * exactly as it did.
 *
 * NOTE for hosts: a camera change moves no border box, so `ResizeObserver`
 * does not fire on it. Put the camera in `layoutKey`.
 */
function scaleOf(container: HTMLElement, containerRect: DOMRect): number {
  if (!container.offsetWidth) return 1;
  const raw = containerRect.width / container.offsetWidth;
  return Math.abs(raw - 1) < 0.005 ? 1 : raw;
}

/** The layer's own space: the container's padding-box origin, with whatever
 *  camera scale sits on it divided back out (`scaleOf`). */
function containerSpace(container: HTMLElement): WireSpace {
  const rect = container.getBoundingClientRect();
  return { left: rect.left, top: rect.top, scale: scaleOf(container, rect) };
}

function centreOf(dot: HTMLElement, space: WireSpace): { x: number; y: number } {
  const rect = dot.getBoundingClientRect();
  return { x: (rect.left + rect.width / 2 - space.left) / space.scale, y: (rect.top + rect.height / 2 - space.top) / space.scale };
}

/** One measured box in the container's own coordinate space — the same
 *  subtraction `centreOf` above does, over a whole rect instead of a dot. */
function boxOf(element: HTMLElement, space: WireSpace): ElbowRect {
  const rect = element.getBoundingClientRect();
  return { x: (rect.left - space.left) / space.scale, y: (rect.top - space.top) / space.scale, w: rect.width / space.scale, h: rect.height / space.scale };
}

/**
 * Every structural box in the fixture, keyed by the id that stamped it.
 * One pass, shared by every elbow wire — `keepOutsFor` then subtracts each
 * wire's own ends and containers from this one list.
 *
 * WHY a REGION contributes its frame and never its corner card, although
 * both carry the same id: the corner card is the region's INTERFACE
 * ("everything is a block" — the card is a real Block, with the region's
 * own `data-block-id`), while the frame is its SCOPE. A cable bypassing a
 * loop has to clear the loop, not squeeze between the corner card and the
 * body underneath it. Keyed by id with the frame written first, so the
 * block pass below cannot overwrite it with the card's much smaller box.
 */
function keepOutRectsOf(container: HTMLElement, space: WireSpace): KeepOutRect[] {
  const rects: KeepOutRect[] = [];
  const seen = new Set<string>();
  const add = (id: string | null, element: HTMLElement) => {
    if (!id || seen.has(id)) return;
    seen.add(id);
    rects.push({ id, ...boxOf(element, space) });
  };
  for (const frame of container.querySelectorAll<HTMLElement>('[data-slot="region-frame"][data-region-id]')) {
    add(frame.getAttribute("data-region-id"), frame);
  }
  // An OPAQUE region has no frame — its root wraps only the card — so the
  // root's own box is the honest keep-out for that id.
  for (const region of container.querySelectorAll<HTMLElement>("[data-region-id]")) {
    add(region.getAttribute("data-region-id"), region);
  }
  for (const arm of container.querySelectorAll<HTMLElement>('[data-slot="region-arm"][data-arm-id]')) {
    add(arm.getAttribute("data-arm-id"), arm);
  }
  for (const block of container.querySelectorAll<HTMLElement>("[data-block-id]")) {
    add(block.getAttribute("data-block-id"), block);
  }
  return rects;
}

export interface ResolvedWire {
  wire: Wire;
  from: TraceTerminalSpec;
  to: TraceTerminalSpec;
  /** The wire's own routing, or {@link DEFAULT_TRACE_ROUTING} — resolved
   *  HERE and not left to `Trace`'s own default, because the layer has to
   *  know the answer one step earlier than `Trace` does: it is what decides
   *  whether this pass collects keep-outs at all. Leaving `undefined` to
   *  fall through to `Trace` drew an elbow with an EMPTY obstacle list, so
   *  a defaulted cable ignored every region frame on the board while an
   *  explicitly-elbow one respected them — two behaviours for one picture. */
  routing: TraceRouting;
  /** Elbow only, and `undefined` for every other routing so `Trace` is
   *  handed the identical prop set it was handed before lane D. */
  obstacles?: ElbowRect[];
  fromBox?: ElbowRect | null;
  toBox?: ElbowRect | null;
}

export interface ResolvedWires {
  resolved: ResolvedWire[];
  unresolvedIds: string[];
}

const EMPTY_STATE: ResolvedWires = { resolved: [], unresolvedIds: [] };

/**
 * Every wire resolved to its two terminal specs, its routing, and — for an
 * elbow — its keep-outs and endpoint boxes: everything `Trace` needs, read
 * off the rendered DOM under `container`, in `space` (default: the
 * container's own, unscaled).
 *
 * Exported for the React Flow host (`hosts/reactFlowHost.tsx`'s kit edge),
 * which hands its viewport element and zoom as `container`/`space` and
 * paints each result through {@link ResolvedWireTrace}. One derivation,
 * two hosts — so a cable routes identically on the static DOM canvas and
 * on its draggable React Flow twin (docs/peps/0005).
 */
export function resolveWires(container: HTMLElement, wires: readonly Wire[], space: WireSpace = containerSpace(container)): ResolvedWires {
  const resolved: ResolvedWire[] = [];
  const unresolvedIds: string[] = [];
  // Measured lazily: a fixture with no elbow wire at all pays nothing, and
  // a fixture with twenty pays once.
  let rects: KeepOutRect[] | null = null;

  wires.forEach((wire) => {
    const fromDot = resolveDot(container, wire.from);
    const toDot = resolveDot(container, wire.to);
    const fromEdge = fromDot ? railEdgeOf(fromDot) : null;
    const toEdge = toDot ? railEdgeOf(toDot) : null;
    if (!fromDot || !toDot || !fromEdge || !toEdge) {
      unresolvedIds.push(wire.id);
      return;
    }
    // ONE ATTACH POINT, and it is the dot's measured centre — no per-cable
    // offset, ever. Zach, 2026-09-19: "edges should always leave from the
    // center of the port… The port only should have 1 connection point in
    // the center. Instead you should show the producer circle that has the
    // number for the number of arrows intersecting at that port."
    // So `fanWires`' perpendicular spread is no longer applied to paint
    // anywhere (it survives in `wiring.ts` as the GROUPING the producer
    // count is derived from — the fact stays, only its expression moved
    // from geometry to a badge). Two cables sharing a pair therefore draw
    // on top of each other on the stub; that overlap is the accepted cost
    // of the rule, not an oversight.
    //
    // The route then starts and ends ON each dot's painted ring, pulled back
    // HERE by that dot's own measured radius (`gap={0}` below). Zach,
    // 2026-09-22: "make the trace end exactly at the port … right now there
    // is this spacing which is not desirable!" — the spacing was `Trace`'s
    // default 16px `TRACE_TERMINAL_GAP`, sized for its own r=9 glyph plus a
    // chevron, landing ~10px short of a real 5.5-6px dot. Per END rather
    // than one `gap` for both, because the two dots need not match (a
    // collapsed stand-in, an `md` function port, a pinned variant).
    const from: TraceTerminalSpec = traceRouteStart(
      { ...centreOf(fromDot, space), dir: fromEdge as TraceDir },
      // Per the wire's own cap: a butt-capped async dash ends ON the ring,
      // a round cap half a stroke short of it (`traceRingGapPx`'s doc).
      traceRingGapPx(portDotRingRadiusPx(paintedDotOf(fromDot)), undefined, traceLinecapOf(wire.variant)),
    );
    const to: TraceTerminalSpec = traceRouteEnd(
      { ...centreOf(toDot, space), dir: OPPOSITE_DIR[toEdge as TraceDir] },
      traceRingGapPx(portDotRingRadiusPx(paintedDotOf(toDot)), undefined, traceLinecapOf(wire.variant)),
    );
    const routing = wire.routing ?? DEFAULT_TRACE_ROUTING;
    if (routing !== "elbow") {
      resolved.push({ wire, from, to, routing });
      return;
    }
    rects ??= keepOutRectsOf(container, space);
    // WHY the endpoint boxes are the `[data-block-id]` roots and not the
    // same rects the keep-out list carries: the router treats them
    // differently on purpose (`elbow/collisionRouting.ts`'s
    // `routeClearsInput` — the first and last leg may cross their OWN card
    // while leaving through the bound port, no later segment may re-enter
    // it), and that asymmetry is what makes a self-loop leave its block,
    // travel around the outside and come back in on the far wall instead
    // of cutting straight across the card it belongs to. A region end
    // resolves to its corner card here, which is correct for the same
    // reason: the dot is ON the card, so the card is the box the first leg
    // has to escape — the frame is already in the keep-out list above.
    //
    // ADDED 2026-09-22 (lane `frame-auto-port-edges`): a dot on a wall's
    // INNER FACE (`components/frame.tsx`, `data-rail-kind="inner-face"`)
    // has NO own card to escape. Its owner box is the whole frame, and the
    // cable it carries runs INSIDE that frame to a member — so "no later
    // segment may re-enter the own box" would forbid every segment of the
    // route, and the router answered with a lap around the frame (measured:
    // a 100px straight run drawn as a 400px loop). The frame is already
    // subtracted from that cable's keep-outs (`keepOutsFor`: it is an end),
    // so the inner face simply has no box. Every other dot is untouched.
    const innerFace = (dot: HTMLElement) => dot.closest('[data-slot="block-port-rail"]')?.getAttribute("data-rail-kind") === "inner-face";
    const fromBlock = innerFace(fromDot) ? null : fromDot.closest<HTMLElement>("[data-block-id]");
    const toBlock = innerFace(toDot) ? null : toDot.closest<HTMLElement>("[data-block-id]");
    resolved.push({
      wire,
      from,
      to,
      routing,
      obstacles: keepOutsFor(wire, rects),
      fromBox: fromBlock ? boxOf(fromBlock, space) : null,
      toBox: toBlock ? boxOf(toBlock, space) : null,
    });
  });

  return { resolved, unresolvedIds };
}

/** Same polyline? A badge only needs re-anchoring when the route actually
 *  moved, and `Trace` reports its geometry on every re-route — including
 *  the ones that land on identical numbers after a no-op re-measure. */
function samePoints(a: readonly Point[] | undefined, b: readonly Point[]): boolean {
  return a !== undefined && a.length === b.length && a.every((p, i) => p.x === b[i].x && p.y === b[i].y);
}

/* ------------------------------------------------------------------ */
/* One resolved wire, painted — shared by every host that routes here   */
/* ------------------------------------------------------------------ */

export interface ResolvedWireTraceProps {
  route: ResolvedWire;
  /** The polyline `Trace` actually drew, in the route's own space. */
  onGeometry?(wireId: string, points: readonly Point[] | null): void;
}

/**
 * The exact `Trace` the layer paints for one {@link ResolvedWire}. Split out
 * of `WireLayer`'s own render so the React Flow host's custom edge paints
 * the SAME element with the SAME props — ring-flush ends (`gap={0}` over
 * the route's own pulled-back terminals), no terminal glyphs, the kit's
 * `markerEnd` default — rather than a second copy that drifts.
 */
export function ResolvedWireTrace({ route, onGeometry }: ResolvedWireTraceProps) {
  const { wire, from, to, routing, obstacles, fromBox, toBox } = route;
  return (
    // `id` is destructured out of both `Trace` and `TraceBody` (it feeds
    // the MARKER's own id, `safeElementId("bbox-trace-head", id)`) and
    // never lands on either `<g>` as a DOM attribute — so a wrapping
    // group is the only way a story can find ONE wire's rendered trace
    // among its siblings. Purely additive: `Trace` itself is untouched.
    //
    // `data-wire-from` states, in the DOM, which port a wire LEFT.
    // That is what lets an assertion about a control MARK be negative
    // and still be checkable — "no wire originates at `<block>/break`"
    // (`controlFlow.acceptance.ts`'s `expectControlMark`) — because a
    // mark is a badge on the block and never an endpoint, and the only
    // honest way to prove an absence is to enumerate what IS there.
    <g data-wire-id={wire.id} data-wire-from={`${wire.from.blockId}/${wire.from.portId}`}>
      <Trace
        id={wire.id}
        from={from}
        to={to}
        routing={routing}
        variant={wire.variant ?? "data"}
        color={wire.color}
        markerEnd={wire.markerEnd}
        terminals={false}
        gap={0}
        obstacles={obstacles}
        fromBox={fromBox}
        toBox={toBox}
        onGeometry={(geometry) => onGeometry?.(wire.id, geometry.points)}
      />
    </g>
  );
}

/* ------------------------------------------------------------------ */
/* WireLayer                                                            */
/* ------------------------------------------------------------------ */

export function WireLayer({ wires, containerRef, layoutKey, onWireGeometry }: WireLayerProps) {
  const [state, setState] = useState<ResolvedWires>(EMPTY_STATE);
  // The port style in force, subscribed through the SAME store every `Port`
  // re-renders from — so a live switch commits the new dots and re-runs the
  // measurement below in one pass. Without it the ring pull-back stayed at
  // the OLD variant's radius until something else moved (2026-09-22 audit).
  const portVariantId = usePortVariant().id;
  // In a ref so a caller's inline arrow does not re-identify
  // `reportGeometry` (which would re-render every `Trace`).
  const onWireGeometryRef = useRef(onWireGeometry);
  onWireGeometryRef.current = onWireGeometry;
  const reportedRef = useRef<Record<string, readonly Point[]>>({});
  // The polyline each badged wire rides, reported by `Trace` itself rather
  // than re-routed here — one derivation, read back (the same rule
  // `trace.tsx` states for its own `sides`). Kept OUT of `state` on
  // purpose: writing it there would give `state.resolved` a new identity on
  // every geometry report, `Trace` would see fresh `obstacles`/`fromBox`
  // objects, re-route, report again, and the layer would never settle.
  const [badgePoints, setBadgePoints] = useState<Record<string, readonly Point[]>>({});

  const reportGeometry = useCallback((wireId: string, points: readonly Point[] | null) => {
    if (!points || points.length < 2) return;
    setBadgePoints((previous) => (samePoints(previous[wireId], points) ? previous : { ...previous, [wireId]: points }));
    // Outside the updater (React may run an updater twice): its own
    // last-seen map, the same "only when the route moved" guard.
    if (!samePoints(reportedRef.current[wireId], points)) {
      reportedRef.current[wireId] = points;
      onWireGeometryRef.current?.(wireId, points);
    }
  }, []);

  // Retract every reported polyline whose wire is no longer drawn. After the
  // children's own layout effects on purpose: a wire resolved in this commit
  // has already reported through its `Trace`, so it is never retracted here.
  useLayoutEffect(() => {
    const drawn = new Set(state.resolved.map(({ wire }) => wire.id));
    for (const wireId of Object.keys(reportedRef.current)) {
      if (drawn.has(wireId)) continue;
      delete reportedRef.current[wireId];
      onWireGeometryRef.current?.(wireId, null);
    }
  }, [state]);

  // …and every one of them when the layer itself goes (re-judge of d97f5ec):
  // a caller that caches polylines by id — the wall-crossing glue — can
  // outlive a conditionally-mounted layer, and would otherwise keep every
  // last route of a layer that no longer exists.
  useLayoutEffect(
    () => () => {
      for (const wireId of Object.keys(reportedRef.current)) onWireGeometryRef.current?.(wireId, null);
      reportedRef.current = {};
    },
    [],
  );

  useLayoutEffect(() => {
    let cancelled = false;
    let frame: number | null = null;
    let observer: ResizeObserver | null = null;

    // Two F1-class races stack here (`BlockPortLane.stories.tsx` names the
    // first for the multi-line lane, and the same reasoning extends to the
    // second):
    //
    //  1. `containerRef` is owned by WHOEVER renders the fixture element
    //     (a story's own bench div, say) and WireLayer only reads it — a
    //     CHILD's layout effect can run before its PARENT's host ref has
    //     actually attached, so `containerRef.current` can be `null` on
    //     this very first pass even though the div is about to exist.
    //  2. Once the container itself exists, a `BlockPort`'s own rails (and
    //     every `[data-port-id]`/`[data-collapsed-ports]` dot on them)
    //     STILL do not exist on that same commit — they wait for
    //     `useBlockBands`'s own layout effect to measure the Block first,
    //     landing one render pass later. A `ResizeObserver` on the
    //     container does not catch it: adding position:absolute rails does
    //     not change the container's own box.
    //
    // `attach` retries every frame until the ref is real, then measures
    // immediately AND schedules one more deferred pass for (2), on top of
    // the steady-state `ResizeObserver`.
    const attach = () => {
      if (cancelled) return;
      const container = containerRef.current;
      if (!container) {
        frame = requestAnimationFrame(attach);
        return;
      }
      const measure = () => setState(resolveWires(container, wires));
      measure();
      frame = requestAnimationFrame(measure);
      observer = new ResizeObserver(measure);
      observer.observe(container);
    };
    attach();

    return () => {
      cancelled = true;
      if (frame !== null) cancelAnimationFrame(frame);
      observer?.disconnect();
    };
    // `wires` and `layoutKey` ARE the re-measure signal (plan §5): a caller
    // bumps `layoutKey` on anything that can move a dot without resizing the
    // container itself — a Block's view flipping between simple/port/
    // expanded, say, which changes where dots sit but not necessarily the
    // fixture's own outer box.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [containerRef, wires, layoutKey, portVariantId]);

  const badged = state.resolved.filter(({ wire }) => wire.badge !== undefined && badgePoints[wire.id]);

  return (
    <>
      <svg
        data-slot="wire-layer"
        data-unresolved-wires={state.unresolvedIds.join(",")}
        width="100%"
        height="100%"
        style={{ position: "absolute", inset: 0, pointerEvents: "none", overflow: "visible" }}
      >
        {state.resolved.map((route) => (
          <ResolvedWireTrace key={route.wire.id} route={route} onGeometry={reportGeometry} />
        ))}
      </svg>
      {/* WHY the pills live in a DOM sibling of the svg rather than inside
          it: `TraceBadge` renders the stock shadcn `Badge`, a Tailwind-styled
          `<span>` (`traceBadge.tsx`'s own header — "WHY DOM and not SVG"), so
          it has to be laid out by CSS, not by SVG user space. Its contract is
          already "an absolutely-positioned sibling of the svg, whose `points`
          are read in the offsetParent's padding box" — this element IS that
          offsetParent, inset to the same box the svg fills, so the polyline
          `Trace` reports needs no conversion at all.

          Rendered only when something is actually badged: a fixture with no
          pills keeps the DOM it had before lane D, down to the node count
          every existing story's `getBoundingClientRect` reads. */}
      {badged.length > 0 && (
        <div data-slot="wire-badges" style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
          {badged.map(({ wire }) => (
            // WHY the OPAQUE stock variant (`TraceBadge`'s own default)
            // rather than the see-through `outline` the lane brief named:
            // the pill sits ON the cable it describes, so a transparent one
            // is read THROUGH by that cable — measured on `BadgeWithSeed`,
            // where the delayed variant's dots ran between the characters
            // of "z⁻¹ = estimate()". An opaque chip occludes the line the
            // same way `trace.crossing.ts`'s casing occludes a crossing
            // cable. It has to come from the stock Badge's own vocabulary
            // and not from a backdrop written here: `skin.test.ts`'s S4
            // coverage list holds this file to "paints nothing of its own —
            // no border, background, box-shadow or stroke", and it is right
            // to.
            <div key={wire.id} data-wire-id={wire.id}>
              <TraceBadge points={badgePoints[wire.id]} t={0.5} value={wire.badge!} size="sm" variant="secondary" />
            </div>
          ))}
        </div>
      )}
    </>
  );
}

// src/components/wiring.ts — `WireLayer`'s paint vocabulary: what a wire
// LOOKS like between two rendered dots, plus how N wires sharing one
// endpoint pair fan apart so they are visibly N (`fanWires`, D-B3).
//
// This file used to be a third thing as well: the connection RECORD, with
// its own derivation (`wiredPortKeys`). That role is absorbed — the record
// is `scene.ts`'s `SceneEdge` (source/target/sourceHandle/targetHandle,
// React Flow's own vocabulary), the derivation is `scene.ts`'s
// `wiredPorts`, and the item-state mapping moved to the adapter
// (`sceneWires.ts`'s `withWiredState`). Deleted here, deliberately:
// `wireEndKey`, `wiredPortKeys`, `withWiredState` — so there is exactly
// ONE model and this module cannot quietly grow back into a second one.
//
// What remains is view-kit only, and this file still imports NOTHING from
// `src/scene/` — `Wire` is a paint instruction a host DERIVES from a scene
// (`sceneWires.ts`), never a record a host authors as its source of truth.
// `WireLayer` (a component) imports this module, and the components-never-
// import-the-scene wall holds precisely because the scene types stay out
// of here, even transitively.
//
// The permission-free stance is unchanged (Zach, 2026-09-17: "draw as many
// wires as you want... even multiple wires between the same two ports") —
// nothing here validates; everything is derivation over whatever list it
// is handed.

import type { TraceMarkerEnd, TraceRouting, TraceVariant } from "./trace.layout";

/* ------------------------------------------------------------------ */
/* The paint instruction                                               */
/* ------------------------------------------------------------------ */

export interface WireEnd {
  blockId: string;
  portId: string;
}

export interface Wire {
  id: string;
  /** The initiating end — an arrowhead, when a wire opts into one
   *  (`markerEnd: "arrow"`), points AT `to`; the default draws none
   *  (`DEFAULT_TRACE_MARKER_END`). A scene edge's source/target map to
   *  from/to with the direction preserved (`sceneWires.ts`). */
  from: WireEnd;
  to: WireEnd;
  /** Default `"data"`; the async gallery passes `"async"` (D-B6's reading
   *  of the donor's "new wires default to async", `asyncRegionModel.ts`). */
  variant?: TraceVariant;
  /** Default is `Trace`'s own default (`"curved"`). */
  routing?: TraceRouting;
  /** Default is `Trace`'s own default (`DEFAULT_TRACE_MARKER_END`, `"none"`). */
  markerEnd?: TraceMarkerEnd;
  color?: string;
  /**
   * Block/region/arm ids this wire is ALLOWED to pass through — the
   * containers its two ends live inside (a host derives it from
   * `ancestorsOf`; `sceneWires.ts`). `WireLayer` treats every other
   * measured box as a keep-out when `routing === "elbow"`: that is the
   * whole of "cables that do not flow through a region must route around
   * it — bypass above or below" (docs/CONTROL-FLOW-PLAN.md, lane D).
   */
  through?: readonly string[];
  /** Text of a pill riding the wire (`TraceBadge`): `z⁻¹` on a delayed
   *  cable, `mut` on an effect cable. Absent = no pill. */
  badge?: string;
}

/* ------------------------------------------------------------------ */
/* Keep-outs (lane D) — CONTRACT STUB, frozen by wiring.test.ts         */
/* ------------------------------------------------------------------ */

/** A measured box a wire may have to avoid, keyed by the id that stamped it
 *  (`data-block-id`, `data-region-id` or `data-arm-id`). Container-local px. */
export interface KeepOutRect {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

/**
 * The obstacles ONE wire routes around: every rect except its own two
 * endpoint blocks and everything in `through`. Input order, always a new
 * array, `{x, y, w, h}` only (an `ElbowRect`) — the endpoint boxes travel
 * separately as the router's `fromBox`/`toBox`.
 */
export function keepOutsFor(
  wire: Pick<Wire, "from" | "to" | "through">,
  rects: readonly KeepOutRect[],
): { x: number; y: number; w: number; h: number }[] {
  // WHY the exclusion set is exactly "my two ends plus `through`", and
  // nothing cleverer: bypass means AVOID EVERYTHING EXCEPT what I am part
  // of. A cable into a block sitting in a branch's arm may enter that
  // region's frame and that one arm — both are in `through`, because both
  // are ancestors of an end — and it may not enter a SIBLING arm, which is
  // not. That is DRAKON's "an arm is entered only from the shared area"
  // made mechanical: the rule is a set membership over measured boxes, not
  // a special case per container kind, so a region, an arm and a plain
  // block are all treated identically here and nothing has to know which
  // is which. The tempting alternative — "skip any rect that CONTAINS an
  // endpoint" — reads equivalent and is not: a sibling arm that happens to
  // overlap an endpoint's box geometrically would be silently entered,
  // and a container the wire genuinely crosses but whose measured rect has
  // not settled yet would be silently kept out.
  const mine = new Set<string>([wire.from.blockId, wire.to.blockId, ...(wire.through ?? [])]);
  // A NEW array of NEW `{x, y, w, h}` objects, in `rects`' own order: the
  // id is the collector's bookkeeping, not the router's vocabulary
  // (`ElbowRoutingObstacle` has no id), and a caller that got the input
  // array back could mutate one layer's measurements from another's.
  return rects
    .filter((rect) => !mine.has(rect.id))
    .map(({ x, y, w, h }) => ({ x, y, w, h }));
}

/* ------------------------------------------------------------------ */
/* Duplicate fan (D-B3)                                                */
/* ------------------------------------------------------------------ */

/**
 * Perpendicular spread between duplicate wires sharing one endpoint pair.
 *
 * NO LONGER APPLIED TO PAINT (2026-09-19). Zach, looking at three cables
 * leaving one `pose` dot at three stacked offsets (`Pasted image
 * 20260919115137.png`): "very bad. edges should always leave from the center
 * of the port… The port only should have 1 connection point in the center.
 * Instead you should show the producer circle that has the number for the
 * number of arrows intersecting at that port."
 *
 * So the FACT this number expressed — "there are N cables here" — survives;
 * only its expression moved, from geometry to a count badge on the dot.
 * `fanWires` below is the grouping that count is derived from, which is why
 * it is still here and still tested rather than deleted: the producer count
 * and any future "which duplicate am I" affordance must agree about what
 * counts as a duplicate, and one function is how they do.
 *
 * The number itself is kept at its measured value so the two halves of the
 * story stay legible in a diff; nothing reads it any more.
 */
export const DUPLICATE_FAN_PX = 14;

/** Unordered: a wire and a same-pair wire drawn the other way (`a→b` beside
 *  `b→a`) still fan against each other — the visible fact is "N wires
 *  between these two dots", not which end either one calls `from`. The same
 *  rule the scene kit's `duplicateEdges` lint applies, restated over the
 *  paint vocabulary, so the lint and the drawing can never disagree about
 *  what counts as a duplicate. */
function unorderedPairKey(a: WireEnd, b: WireEnd): string {
  const ka = `${a.blockId}/${a.portId}`;
  const kb = `${b.blockId}/${b.portId}`;
  return ka <= kb ? `${ka}|${kb}` : `${kb}|${ka}`;
}

export interface WireFan {
  /** This wire's 0-based rank among the others sharing its endpoint pair. */
  index: number;
  /** How many wires share this endpoint pair, this one included. */
  count: number;
  /** The `curve` offset `Trace` already understands (`trace.routing.ts`'s
   *  `TraceCurve`) — `{dx: 0, dy: ...}` per plan §5, centred on 0 so a lone
   *  wire between a pair fans by nothing at all. */
  offset: { dx: number; dy: number };
}

/** One `WireFan` per wire, in `wires`' own order. `index`/`count` are the
 *  live half — "this is cable 2 of 3 between these two dots", which is what
 *  a producer-count badge reports; `offset` is no longer applied to paint
 *  (see `DUPLICATE_FAN_PX`). */
export function fanWires(wires: readonly Wire[]): WireFan[] {
  const idsByPair = new Map<string, string[]>();
  for (const wire of wires) {
    const key = unorderedPairKey(wire.from, wire.to);
    const ids = idsByPair.get(key);
    if (ids) ids.push(wire.id);
    else idsByPair.set(key, [wire.id]);
  }
  const rankById = new Map<string, { index: number; count: number }>();
  for (const ids of idsByPair.values()) {
    ids.forEach((id, index) => rankById.set(id, { index, count: ids.length }));
  }
  return wires.map((wire) => {
    const rank = rankById.get(wire.id)!;
    const dy = (rank.index - (rank.count - 1) / 2) * DUPLICATE_FAN_PX;
    return { index: rank.index, count: rank.count, offset: { dx: 0, dy } };
  });
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// src/skin/portVariants.ts — the port's VISUAL VARIANT registry: five
// circular, on-the-edge port styles, selectable by one attribute on
// `<html>` (`<html data-bbox-port-variant="v3">`) or by an explicit
// `variant` prop, defaulting to `v1`.
//
// Zach, 2026-09-19 (docs/ASK-2026-09-19-PORTS-EDGES-REGIONS-FEEDBACK.md):
// "the ports look way too big right now and the port text size also seems
// too big … generally it looks very unprofessional … I want the port text
// to be 'small' by default … one proposal should be based on the original
// SystemSketch source code, one on langflow … I only want to see proposals
// that explore circular ports … proposals where the ports are on the edge,
// not where they are inset."
//
// WHAT A VARIANT DECIDES — and only this: the dot's box diameter, the two
// rings painted OUTSIDE that box (the card-coloured `gap`, then the `ring`),
// which PAINT GRAMMAR maps the value state (empty · valueSet · wired ·
// received) onto those three circles, the label/type typography, and the
// hover / selected / producers-circle treatments. It never decides WHERE a
// dot sits: every variant is centred ON the block wall, half outside, by
// `BlockPort`'s rail geometry — the one rule that is not a proposal (the
// anti-example is `115744`, square handles inset inside the node body).
//
// WHY every variant keeps the SAME text rung (`xs`, 12px): "small by
// default" is the one thing Zach ruled outright, and the next rung up
// (`sm`, 18px) is exactly the size he called too big. So the five vary
// what a reviewer actually compares at that size — dot scale (11 → 16px
// painted), fill grammar, colour source (state vs. type), typeface and
// weight — and the text never jumps when he flips between them.
//
// WHY CSS custom properties AND a typed table, not one or the other: the
// components need NUMBERS (a label is placed from the dot's box, the sketch
// skin's boundary pass reads `data-bbox-ring-expand`), so this table is the
// source of truth and every port root publishes its resolved variant as
// inline `--bbox-port-*` properties. `portVariants.css` carries the SAME
// values under `[data-bbox-port-variant]` blocks for CSS-only consumers
// (the regions lane's frame inset, a host's chrome) and holds the
